#!/usr/bin/env node
import fs from "fs";
import path from "path";

const FILES = {
  "apps/frontend/src/pages/Compta.tsx": "// apps/frontend/src/pages/Compta.tsx\nimport React, { useMemo, useRef, useState, useEffect } from \"react\";\nimport { useNavigate } from \"react-router-dom\";\nimport {\n  FileBarChart,\n  CloudUpload,\n  Loader2,\n  TrendingUp,\n  TrendingDown,\n  ReceiptEuro,\n  CheckCircle2,\n  Sparkles,\n  AlertTriangle,\n  Table2,\n  Download,\n} from \"lucide-react\";\nimport { useAuth } from \"../store/auth.store\";\nimport { useComptaReportStore } from \"../store/comptaReport.store\";\nimport { useExpertAssistantStore } from \"../features/ai/expertAssistant.store\";\nimport { z } from \"zod\";\nimport { ApiRequestError } from \"../utils/apiRequestError\";\nimport { toast } from \"react-hot-toast\";\n\n// ✅ AJOUT\nimport type { AiRunResponse } from \"../api/types\";\n\n/**\n * Helpers formats\n */\nconst IsoDateTime = z.string().refine(\n  (v: string) => !Number.isNaN(Date.parse(v)),\n  \"generatedAt must be a valid ISO datetime string\"\n);\n\nconst YearMonth = z.string().regex(/^\\d{4}-\\d{2}$/, \"month must be YYYY-MM\");\n\n/**\n * Severity aligned with your report needs\n */\nconst AnomalySeverity = z.enum([\"info\", \"warn\", \"critical\"]);\n\nexport const ComptaReportSchema = z.object({\n  meta: z.object({\n    currency: z.string().default(\"EUR\"),\n    sourceFileName: z\n      .string()\n      .optional()\n      .nullable()\n      .transform((v) => (v == null ? undefined : v)),\n    generatedAt: IsoDateTime,\n    sheets: z.array(z.string()),\n    rowsTotal: z.number(),\n  }),\n\n  totals: z.object({\n    recettesHT: z.number(),\n    recettesTTC: z.number(),\n    depensesHT: z.number(),\n    depensesTTC: z.number(),\n    resultatNet: z.number(),\n  }),\n\n  tva: z.object({\n    collectee: z.number(),\n    deductible: z.number(),\n    aPayer: z.number(),\n    parTaux: z\n      .array(\n        z.object({\n          taux: z.number(),\n          baseHT: z.number(),\n          tva: z.number(),\n          type: z.enum([\"vente\", \"achat\"]),\n        })\n      )\n      .default([]),\n  }),\n\n  breakdown: z.object({\n    parMois: z\n      .array(\n        z.object({\n          month: YearMonth,\n          recettesHT: z.number(),\n          depensesHT: z.number(),\n          resultatNet: z.number(),\n          tvaCollectee: z.number(),\n          tvaDeductible: z.number(),\n        })\n      )\n      .default([]),\n\n    topRecettes: z\n      .array(\n        z.object({\n          label: z.string(),\n          amountHT: z.number(),\n          count: z.number(),\n        })\n      )\n      .default([]),\n\n    topDepenses: z\n      .array(\n        z.object({\n          label: z.string(),\n          amountHT: z.number(),\n          count: z.number(),\n        })\n      )\n      .default([]),\n  }),\n\n  anomalies: z\n    .array(\n      z.object({\n        severity: AnomalySeverity,\n        message: z.string(),\n        sheet: z\n          .string()\n          .optional()\n          .nullable()\n          .transform((v) => (v == null ? undefined : v)),\n        rowIndex: z\n          .number()\n          .optional()\n          .nullable()\n          .transform((v) => (v == null ? undefined : v)),\n      })\n    )\n    .default([]),\n\n  data: z.object({\n    sheets: z.record(\n      z.string(),\n      z.object({\n        columns: z.array(z.string()),\n        rows: z.array(z.array(z.unknown())),\n        truncated: z.boolean().optional(),\n      })\n    ),\n  }),\n\n  summary: z.object({\n    resume: z.string(),\n    actions: z.array(z.string()).default([]),\n    questions: z.array(z.string()).default([]),\n  }),\n});\n\nexport type ComptaReport = z.infer<typeof ComptaReportSchema>;\n\nconst API_URL = import.meta.env.VITE_API_URL\n  ? `${import.meta.env.VITE_API_URL.replace(/\\/$/, \"\")}/ai`\n  : \"http://localhost:8080/ai\";\n\nexport default function Compta() {\n  const { accessToken } = useAuth();\n  const navigate = useNavigate();\n\n  const setDashboardReport = useComptaReportStore((s) => s.setReport);\n  const openWith = useExpertAssistantStore((s) => s.openWith);\n\n  const [file, setFile] = useState<File | null>(null);\n  const [jobId, setJobId] = useState<string | null>(null);\n\n  // ✅ MODIF: stocker analysisId renvoyé par /ai/run\n  const [analysisId, setAnalysisId] = useState<string | null>(null);\n\n  const [isProcessing, setIsProcessing] = useState(false);\n  const [rawResult, setRawResult] = useState<any>(null);\n  const [report, setReport] = useState<ComptaReport | null>(null);\n  const [schemaError, setSchemaError] = useState<string | null>(null);\n\n  const inputRef = useRef<HTMLInputElement | null>(null);\n\n  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);\n  const isPollingRef = useRef(false);\n\n  // ✅ AJOUT UNIQUE : éviter double fetch (React 18 StrictMode)\n  const didHydrateRef = useRef(false);\n\n  useEffect(() => {\n    return () => {\n      if (pollRef.current) {\n        clearInterval(pollRef.current);\n        pollRef.current = null;\n      }\n      isPollingRef.current = false;\n    };\n  }, []);\n\n  const safeParseResult = (value: any) => {\n    if (!value) return value;\n    if (typeof value === \"string\") {\n      const cleaned = value.replace(/```json|```/gi, \"\").trim();\n      try {\n        return JSON.parse(cleaned);\n      } catch {\n        return cleaned;\n      }\n    }\n    return value;\n  };\n\n  const clearPoll = () => {\n    if (pollRef.current) {\n      clearInterval(pollRef.current);\n      pollRef.current = null;\n    }\n    isPollingRef.current = false;\n  };\n\n  const startPolling = (id: string) => {\n    clearPoll();\n\n    if (isPollingRef.current) return;\n    isPollingRef.current = true;\n\n    let delayMs = 3000;\n    const maxDelayMs = 10000;\n\n    const tick = async () => {\n      try {\n        const response = await fetch(`${API_URL}/status/${id}`, {\n          headers: { Authorization: `Bearer ${accessToken}` },\n        });\n\n        if (response.status === 304) return;\n\n        if (response.status === 429) {\n          clearPoll();\n          delayMs = Math.min(maxDelayMs, delayMs * 2);\n          isPollingRef.current = true;\n          pollRef.current = setInterval(tick, delayMs);\n          return;\n        }\n\n        const data = await response.json();\n\n        if (data.status === \"completed\") {\n          clearPoll();\n          setIsProcessing(false);\n\n          const parsed = safeParseResult(data.result);\n          setRawResult(parsed);\n\n          const validated = ComptaReportSchema.safeParse(parsed);\n          if (!validated.success) {\n            setReport(null);\n            setSchemaError(\n              \"Le serveur a renvoyé un JSON invalide (format ComptaReport).\"\n            );\n            return;\n          }\n\n          setSchemaError(null);\n          setReport(validated.data);\n\n          setDashboardReport(validated.data);\n        }\n\n        if (data.status === \"failed\") {\n          clearPoll();\n          setIsProcessing(false);\n          setReport(null);\n          setSchemaError(null);\n          setRawResult(null);\n          toast.error(data.error || \"L'analyse comptable a échoué.\");\n        }\n      } catch (e) {\n        clearPoll();\n        setIsProcessing(false);\n\n        const err = e as ApiRequestError;\n        if (err?.code === \"quota_exceeded\") {\n          toast.error(\"Quota atteint. Passez en PRO pour continuer.\");\n          navigate(\"/upgrade\");\n        } else {\n          toast.error(err?.message || \"Erreur pendant l'analyse.\");\n        }\n      }\n    };\n\n    tick();\n    pollRef.current = setInterval(tick, delayMs);\n  };\n\n  // ✅ AJOUT UNIQUE : Option B — recharger le dernier report via /ai/compta/latest\n  useEffect(() => {\n    if (!accessToken) return;\n    if (didHydrateRef.current) return;\n    if (isProcessing) return;\n    if (report) return;\n\n    didHydrateRef.current = true;\n\n    (async () => {\n      try {\n        const res = await fetch(`${API_URL}/compta/latest`, {\n          headers: { Authorization: `Bearer ${accessToken}` },\n        });\n\n        const json = (await res.json()) as any;\n\n        if (!res.ok || !json?.report) {\n          return;\n        }\n\n        const parsed = safeParseResult(json.report);\n        setRawResult(parsed);\n\n        const validated = ComptaReportSchema.safeParse(parsed);\n        if (!validated.success) {\n          setSchemaError(\n            \"Le serveur a renvoyé un JSON invalide (format ComptaReport).\"\n          );\n          return;\n        }\n\n        setSchemaError(null);\n        setReport(validated.data);\n        setDashboardReport(validated.data);\n\n        if (json?.id) {\n          setAnalysisId(String(json.id));\n        }\n      } catch {\n        // silencieux : on ne bloque pas la page si le réseau échoue\n      }\n    })();\n  }, [accessToken, isProcessing, report]);\n\n  const handleUpload = async () => {\n    if (!file) return;\n\n    if (!accessToken) {\n      toast.error(\"Vous devez être connecté.\");\n      return;\n    }\n\n    clearPoll();\n\n    setIsProcessing(true);\n    setReport(null);\n    setRawResult(null);\n    setSchemaError(null);\n\n    // ✅ MODIF: reset analysisId au lancement\n    setAnalysisId(null);\n\n    const form = new FormData();\n    form.append(\"type\", \"compta\");\n    form.append(\"file\", file);\n\n    try {\n      const response = await fetch(`${API_URL}/run`, {\n        method: \"POST\",\n        headers: { Authorization: `Bearer ${accessToken}` },\n        body: form,\n      });\n\n      const data = (await response.json()) as AiRunResponse;\n\n      if (!data.jobId) {\n        setIsProcessing(false);\n        toast.error((data as any)?.error || \"Erreur lors du lancement.\");\n        return;\n      }\n\n      // ✅ MODIF: récupérer analysisId si renvoyé par le backend\n      setAnalysisId(\n        (data as any)?.analysisId ? String((data as any).analysisId) : null\n      );\n\n      setJobId(String(data.jobId));\n      startPolling(String(data.jobId));\n    } catch (e) {\n      setIsProcessing(false);\n\n      const err = e as ApiRequestError;\n      if (err?.code === \"quota_exceeded\") {\n        toast.error(\"Quota atteint. Passez en PRO pour continuer.\");\n        navigate(\"/upgrade\");\n      } else {\n        toast.error(err?.message || \"Erreur lors du lancement.\");\n      }\n    }\n  };\n\n  // ✅ MODIF UNIQUE: au clic Mode Expert IA, NE PLUS naviguer vers /dashboard\n  const handleExpertChat = async () => {\n    if (!accessToken) {\n      toast.error(\"Vous devez être connecté.\");\n      return;\n    }\n\n    const resultatNet = Number(report?.totals?.resultatNet ?? 0) || 0;\n\n    let finalAnalysisId = analysisId;\n\n    try {\n      const res = await fetch(`${API_URL}/compta/latest`, {\n        headers: { Authorization: `Bearer ${accessToken}` },\n      });\n\n      const json = (await res.json()) as any;\n\n      if (!res.ok || !json?.id) {\n        toast.error(\"Impossible de retrouver l’analyse compta à utiliser.\");\n        return;\n      }\n\n      finalAnalysisId = String(json.id);\n      setAnalysisId(finalAnalysisId);\n    } catch {\n      toast.error(\"Erreur réseau lors de la récupération de l’analyse compta.\");\n      return;\n    }\n\n    openWith({\n      source: \"compta\",\n      message: `Analyse expert activée ! Résultat net estimé: ${resultatNet}€. Que veux-tu optimiser (TVA, charges, marge, trésorerie) ?`,\n      analysisData: report,\n      createdAt: new Date().toISOString(),\n    });\n\n    const event = new CustomEvent(\"openExpertChat\", {\n      detail: {\n        analysisId: finalAnalysisId,\n        message: `Analyse expert activée ! Résultat net estimé: ${resultatNet}€. Que veux-tu optimiser (TVA, charges, marge, trésorerie) ?`,\n      },\n    });\n    window.dispatchEvent(event);\n\n    // ✅ MODIF: on reste sur la page Compta (plus de navigate(\"/dashboard\"))\n    // navigate(\"/dashboard\");\n  };\n\n  const downloadJson = () => {\n    if (!jobId) return;\n    window.open(`${API_URL}/export/${jobId}?format=json`, \"_blank\");\n  };\n\n  const downloadCsv = () => {\n    if (!jobId) return;\n    window.open(`${API_URL}/export/${jobId}?format=csv`, \"_blank\");\n  };\n\n  const totals = report?.totals;\n  const tva = report?.tva;\n\n  const profitColor =\n    totals && totals.resultatNet >= 0 ? \"text-emerald-600\" : \"text-red-600\";\n\n  const anomaliesCount = report?.anomalies?.length ?? 0;\n\n  const previewSheets = useMemo(() => {\n    if (!report?.data?.sheets) return [];\n    return Object.entries(report.data.sheets).map(([name, table]) => ({\n      name,\n      columns: table.columns,\n      rows: table.rows,\n      truncated: !!table.truncated,\n    }));\n  }, [report]);\n\n  return (\n    <div className=\"p-6 pb-32\">\n      <div className=\"flex items-center gap-3 mb-6\">\n        <div className=\"w-12 h-12 rounded-2xl bg-emerald-600 text-white flex items-center justify-center shadow-lg\">\n          <FileBarChart size={22} />\n        </div>\n        <div>\n          <h2 className=\"text-2xl font-black text-[var(--theme-text)] leading-tight\">\n            Compta IA\n          </h2>\n          <p className=\"text-sm text-slate-500 font-semibold\">\n            Analyse XLSX/CSV → Rapport structuré + preview + exports\n          </p>\n        </div>\n      </div>\n\n      {/* Upload Card */}\n      <div className=\"bg-[var(--theme-card)] rounded-3xl border border-slate-100 shadow-sm p-5\">\n        <div className=\"flex flex-col gap-3\">\n          <input\n            ref={inputRef}\n            type=\"file\"\n            accept=\".xlsx,.csv\"\n            className=\"hidden\"\n            onChange={(e) => setFile(e.target.files?.[0] ?? null)}\n          />\n\n          <div className=\"flex flex-wrap gap-3 items-center\">\n            <button\n              onClick={() => inputRef.current?.click()}\n              className=\"px-4 py-3 rounded-2xl bg-slate-900 text-white font-black text-xs uppercase tracking-widest flex items-center gap-2\"\n            >\n              <CloudUpload size={16} />\n              Choisir un fichier\n            </button>\n\n            {file && (\n              <span className=\"text-sm font-bold text-slate-700\">\n                {file.name}\n              </span>\n            )}\n\n            <button\n              onClick={handleUpload}\n              disabled={!file || isProcessing}\n              className=\"px-4 py-3 rounded-2xl bg-emerald-600 text-white font-black text-xs uppercase tracking-widest disabled:opacity-50\"\n            >\n              {isProcessing ? \"Analyse…\" : \"Lancer analyse\"}\n            </button>\n          </div>\n\n          {schemaError && (\n            <div className=\"mt-3 text-sm text-red-600 font-semibold\">\n              {schemaError}\n            </div>\n          )}\n        </div>\n      </div>\n\n      {/* Results */}\n      {report && (\n        <div className=\"mt-6 space-y-6\">\n          {/* KPI */}\n          <div className=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n            <div className=\"bg-[var(--theme-card)] rounded-3xl border border-slate-100 shadow-sm p-5\">\n              <div className=\"flex items-center gap-2 text-slate-500 font-black text-xs uppercase tracking-widest\">\n                <ReceiptEuro size={14} />\n                Recettes\n              </div>\n              <div className=\"mt-3 text-2xl font-black text-[var(--theme-text)]\">\n                {totals?.recettesTTC?.toFixed(2)} €\n              </div>\n            </div>\n\n            <div className=\"bg-[var(--theme-card)] rounded-3xl border border-slate-100 shadow-sm p-5\">\n              <div className=\"flex items-center gap-2 text-slate-500 font-black text-xs uppercase tracking-widest\">\n                <TrendingDown size={14} />\n                Dépenses\n              </div>\n              <div className=\"mt-3 text-2xl font-black text-[var(--theme-text)]\">\n                {totals?.depensesTTC?.toFixed(2)} €\n              </div>\n            </div>\n\n            <div className=\"bg-[var(--theme-card)] rounded-3xl border border-slate-100 shadow-sm p-5\">\n              <div className=\"flex items-center gap-2 text-slate-500 font-black text-xs uppercase tracking-widest\">\n                <TrendingUp size={14} />\n                Résultat net\n              </div>\n              <div className={`mt-3 text-2xl font-black ${profitColor}`}>\n                {totals?.resultatNet?.toFixed(2)} €\n              </div>\n            </div>\n          </div>\n\n          {/* TVA */}\n          <div className=\"bg-[var(--theme-card)] rounded-3xl border border-slate-100 shadow-sm p-5\">\n            <div className=\"flex items-center justify-between\">\n              <h3 className=\"text-xs font-black uppercase tracking-widest text-[var(--theme-text)]\">\n                TVA\n              </h3>\n              <span className=\"text-xs font-bold text-slate-500\">\n                {report.meta.currency}\n              </span>\n            </div>\n\n            <div className=\"mt-4 grid grid-cols-1 md:grid-cols-3 gap-4\">\n              <div className=\"bg-[var(--theme-bg)] border border-slate-100 rounded-2xl p-4\">\n                <div className=\"text-xs font-black uppercase tracking-widest text-slate-500\">\n                  Collectée\n                </div>\n                <div className=\"mt-2 text-xl font-black text-[var(--theme-text)]\">\n                  {tva?.collectee?.toFixed(2)} €\n                </div>\n              </div>\n\n              <div className=\"bg-[var(--theme-bg)] border border-slate-100 rounded-2xl p-4\">\n                <div className=\"text-xs font-black uppercase tracking-widest text-slate-500\">\n                  Déductible\n                </div>\n                <div className=\"mt-2 text-xl font-black text-[var(--theme-text)]\">\n                  {tva?.deductible?.toFixed(2)} €\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-2xl p-4 text-white\">\n                <div className=\"text-xs font-black uppercase tracking-widest text-white/70\">\n                  À payer\n                </div>\n                <div className=\"mt-2 text-xl font-black\">\n                  {tva?.aPayer?.toFixed(2)} €\n                </div>\n              </div>\n            </div>\n          </div>\n\n          {/* Preview */}\n          <div className=\"bg-[var(--theme-card)] rounded-3xl border border-slate-100 shadow-sm p-5\">\n            <div className=\"flex items-center justify-between gap-3 flex-wrap\">\n              <h3 className=\"text-xs font-black uppercase tracking-widest text-[var(--theme-text)] flex items-center gap-2\">\n                <Table2 size={14} />\n                Preview\n              </h3>\n\n              <div className=\"flex gap-2\">\n                <button\n                  onClick={downloadJson}\n                  className=\"px-3 py-2 rounded-2xl bg-slate-100 text-slate-700 font-black text-xs uppercase tracking-widest flex items-center gap-2\"\n                >\n                  <Download size={14} /> JSON\n                </button>\n                <button\n                  onClick={downloadCsv}\n                  className=\"px-3 py-2 rounded-2xl bg-slate-100 text-slate-700 font-black text-xs uppercase tracking-widest flex items-center gap-2\"\n                >\n                  <Download size={14} /> CSV\n                </button>\n              </div>\n            </div>\n\n            <div className=\"mt-4 space-y-4\">\n              {previewSheets.map((s) => (\n                <div\n                  key={s.name}\n                  className=\"border border-slate-100 rounded-2xl overflow-hidden\"\n                >\n                  <div className=\"px-4 py-3 bg-[var(--theme-bg)] flex items-center justify-between\">\n                    <div className=\"font-black text-xs uppercase tracking-widest text-slate-700\">\n                      {s.name}\n                    </div>\n                    {s.truncated && (\n                      <div className=\"text-xs font-bold text-amber-700 flex items-center gap-2\">\n                        <AlertTriangle size={14} />\n                        Preview tronquée\n                      </div>\n                    )}\n                  </div>\n\n                  <div className=\"overflow-x-auto\">\n                    <table className=\"min-w-full text-sm\">\n                      <thead className=\"bg-[var(--theme-card)]\">\n                        <tr>\n                          {s.columns.map((c, idx) => (\n                            <th\n                              key={idx}\n                              className=\"text-left px-4 py-2 text-xs font-black uppercase tracking-widest text-slate-500\"\n                            >\n                              {c}\n                            </th>\n                          ))}\n                        </tr>\n                      </thead>\n                      <tbody className=\"bg-[var(--theme-card)]\">\n                        {s.rows.slice(0, 10).map((row, rIdx) => (\n                          <tr key={rIdx} className=\"border-t border-slate-100\">\n                            {row.map((cell, cIdx) => (\n                              <td\n                                key={cIdx}\n                                className=\"px-4 py-2 text-slate-700\"\n                              >\n                                {String(cell ?? \"\")}\n                              </td>\n                            ))}\n                          </tr>\n                        ))}\n                      </tbody>\n                    </table>\n                  </div>\n\n                  <div className=\"px-4 py-3 bg-[var(--theme-bg)] text-xs text-slate-600 font-semibold\">\n                    Affichage: 10 lignes (preview). Export disponible via\n                    boutons.\n                  </div>\n                </div>\n              ))}\n            </div>\n          </div>\n\n          {/* Summary + Expert */}\n          <div className=\"bg-[var(--theme-card)] rounded-3xl border border-slate-100 shadow-sm p-5\">\n            <div className=\"flex items-center justify-between gap-3 flex-wrap\">\n              <div className=\"flex items-center gap-2\">\n                <CheckCircle2 size={16} className=\"text-emerald-600\" />\n                <h3 className=\"text-xs font-black uppercase tracking-widest text-[var(--theme-text)]\">\n                  Résumé\n                </h3>\n              </div>\n              <div className=\"text-xs font-bold text-slate-500\">\n                Anomalies: {anomaliesCount}\n              </div>\n            </div>\n\n            <p className=\"mt-3 text-sm text-slate-700 whitespace-pre-wrap\">\n              {report.summary.resume}\n            </p>\n\n            <div className=\"mt-4\">\n              <button\n                onClick={handleExpertChat}\n                className=\"w-full py-4 rounded-2xl bg-gradient-to-tr from-purple-600 to-blue-600 text-white font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2\"\n              >\n                <Sparkles size={16} />\n                Mode Expert IA\n              </button>\n              <p className=\"mt-2 text-xs text-slate-500 font-semibold\">\n                Ouvre la bulle trans-onglet et injecte l’analyse dans le chat\n                expert.\n              </p>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {!report && isProcessing && (\n        <div className=\"mt-6 bg-[var(--theme-card)] rounded-3xl border border-slate-100 shadow-sm p-5 flex items-center gap-3 text-slate-700 font-bold\">\n          <Loader2 className=\"animate-spin\" size={18} />\n          Analyse en cours…\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "apps/frontend/src/pages/Vision.tsx": "// apps/frontend/src/pages/Vision.tsx\nimport React, { useState, useRef } from \"react\";\nimport { Camera, ShieldCheck, Loader2, Sparkles } from \"lucide-react\";\nimport { useAuth } from \"../store/auth.store\";\nimport { useNavigate } from \"react-router-dom\";\nimport { fetchWithAuth } from \"../auth/fetchWithAuth\";\nimport {\n  useUser,\n  normalizePlan,\n  normalizeStatus,\n  isProActive,\n} from \"../context/user.context\";\nimport { ApiRequestError } from \"../utils/apiRequestError\";\nimport { toast } from \"react-hot-toast\";\n\nexport default function Vision() {\n  const [isProcessing, setIsProcessing] = useState(false);\n  const [analysis, setAnalysis] = useState<any>(null);\n  const fileInputRef = useRef<HTMLInputElement>(null);\n  const navigate = useNavigate();\n\n  const { user } = useAuth();\n  const { userData, setUserData } = useUser();\n\n  // ✅ MODIF 1: lock + throttle pour éviter les refresh quota en boucle\n  const quotaRefreshInFlightRef = useRef(false);\n  const lastQuotaRefreshAtRef = useRef(0);\n\n  const refreshQuotaFromDashboard = async () => {\n    // ✅ throttle: 1 refresh max / 3 secondes\n    const now = Date.now();\n    if (quotaRefreshInFlightRef.current) return;\n    if (now - lastQuotaRefreshAtRef.current < 3000) return;\n\n    quotaRefreshInFlightRef.current = true;\n    lastQuotaRefreshAtRef.current = now;\n\n    try {\n      const data = await fetchWithAuth<any>(\"/dashboard\", { method: \"GET\" });\n\n      // ✅ MODIF 2: setUserData doit recevoir un UserData direct (pas une fonction)\n      const rawPlan = data?.subscription?.plan ?? userData?.plan ?? \"free\";\n      const rawStatus =\n        data?.subscription?.status ?? userData?.status ?? \"inactive\";\n\n      const plan = normalizePlan(rawPlan);\n      const status = normalizeStatus(rawStatus);\n      const proActive = isProActive(plan, status);\n\n      setUserData({\n        ...(userData ?? {}),\n        email: userData?.email ?? user?.email ?? undefined,\n        plan,\n        status,\n        quota: proActive\n          ? undefined\n          : {\n              used: Number(data?.quota?.used ?? 0),\n              limit: Number(data?.quota?.limit ?? 0),\n            },\n      } as any);\n    } catch {\n      // best effort\n    } finally {\n      quotaRefreshInFlightRef.current = false;\n    }\n  };\n\n  const sendToExpertMode = (payload: any) => {\n    navigate(\"/assistant\");\n\n    window.dispatchEvent(\n      new CustomEvent(\"openExpertChat\", {\n        detail: {\n          analysisData: payload,\n          message:\n            \"Voici une analyse Vision. Donne-moi une interprétation détaillée, les risques, et un plan d’action concret (matériel, étapes, sécurité).\",\n        },\n      })\n    );\n  };\n\n  const handlePhoto = async (e: React.ChangeEvent<HTMLInputElement>) => {\n    const file = e.target.files?.[0];\n    if (!file) return;\n\n    setIsProcessing(true);\n    setAnalysis(null);\n\n    const form = new FormData();\n    form.append(\"image\", file);\n\n    try {\n      const res = await fetchWithAuth<any>(\"/vision/analyze\", {\n        method: \"POST\",\n        body: form,\n      });\n\n      const data = res;\n\n      setAnalysis(data);\n\n      await refreshQuotaFromDashboard();\n    } catch (e) {\n      const err = e as ApiRequestError;\n\n      if (err.code === \"quota_exceeded\") {\n        toast.error(\"Quota atteint. Passez en PRO pour continuer.\");\n        navigate(\"/upgrade\");\n      } else {\n        toast.error(err.message || \"Erreur lors de l'analyse.\");\n      }\n    } finally {\n      setIsProcessing(false);\n      if (fileInputRef.current) fileInputRef.current.value = \"\";\n    }\n  };\n\n  return (\n    <div className=\"h-full max-w-md mx-auto flex flex-col gap-3 overflow-hidden animate-in fade-in duration-500\">\n      <input\n        type=\"file\"\n        ref={fileInputRef}\n        onChange={handlePhoto}\n        accept=\"image/*\"\n        capture=\"environment\"\n        className=\"hidden\"\n      />\n\n      <div className=\"bg-[var(--theme-card)] rounded-2xl p-4 border border-slate-100 shadow-sm shrink-0\">\n        <div className=\"flex items-center gap-2 mb-3\">\n          <span className=\"text-emerald-500 text-xs\">📄</span>\n          <span className=\"text-[9px] font-black text-slate-400 uppercase tracking-widest\">\n            Base de connaissance externe\n          </span>\n        </div>\n\n        {/* ✅ Import catalogue (inchangé) */}\n        <div\n          onClick={() => !isProcessing && fileInputRef.current?.click()}\n          className=\"border-2 border-dashed border-slate-50 rounded-xl py-4 flex flex-col items-center justify-center gap-1 text-slate-400 hover:bg-[var(--theme-bg)] transition-colors cursor-pointer group\"\n        >\n          <span className=\"text-[11px] font-medium italic opacity-60 flex items-center gap-2\">\n            ☁️ Importer un catalogue (Excel/CSV)\n          </span>\n        </div>\n      </div>\n\n      <div className=\"flex-1 bg-[var(--theme-card)] rounded-[2rem] p-6 shadow-sm flex flex-col min-h-0 overflow-y-auto\">\n        <div className=\"flex justify-between items-center mb-3\">\n          <h2 className=\"text-lg font-black text-[var(--theme-text)] tracking-tight uppercase\">\n            Suivi de Chantier\n          </h2>\n          <span className=\"bg-emerald-50 text-emerald-600 text-[8px] font-black px-2 py-0.5 rounded-md flex items-center gap-1 border border-emerald-100 uppercase\">\n            <ShieldCheck size={10} /> IA Vision Expert\n          </span>\n        </div>\n\n        {!analysis ? (\n          <>\n            <p className=\"text-slate-400 text-[12px] leading-snug italic mb-6\">\n              Prenez une photo. L'IA analyse l'avancement technique et les\n              matériaux sans identifier les personnes.\n            </p>\n\n            {/* ✅ MODIF UNIQUE: \"Prendre une photo\" déclenche l'appareil photo (input capture) */}\n            <div\n              onClick={() => !isProcessing && fileInputRef.current?.click()}\n              className=\"flex-1 border-2 border-dashed border-slate-100 rounded-[1.5rem] flex flex-col items-center justify-center group cursor-pointer hover:bg-[var(--theme-bg)] transition-all mb-2 min-h-[200px]\"\n            >\n              {isProcessing ? (\n                <div className=\"flex flex-col items-center gap-3\">\n                  <Loader2 className=\"w-12 h-12 text-[#4f46e5] animate-spin\" />\n                  <span className=\"text-[11px] font-bold text-blue-500 uppercase animate-pulse\">\n                    Analyse technique...\n                  </span>\n                </div>\n              ) : (\n                <>\n                  <div className=\"w-14 h-14 bg-[var(--theme-card)] rounded-full shadow-md flex items-center justify-center text-[#4f46e5] mb-3 border border-slate-50 group-hover:scale-105 transition-transform\">\n                    <Camera size={24} />\n                  </div>\n                  <span className=\"font-black text-[var(--theme-text)] text-[13px] uppercase tracking-wide\">\n                    Prendre une photo\n                  </span>\n                  <span className=\"text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5\">\n                    Analyse instantanée\n                  </span>\n                </>\n              )}\n            </div>\n          </>\n        ) : (\n          <div className=\"space-y-4 animate-in slide-in-from-bottom-4 duration-500\">\n            <pre className=\"text-[11px] whitespace-pre-wrap\">\n              {JSON.stringify(analysis, null, 2)}\n            </pre>\n\n            <button\n              onClick={() => sendToExpertMode(analysis)}\n              className=\"w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-bold uppercase tracking-widest flex items-center justify-center gap-2\"\n            >\n              <Sparkles size={14} />\n              Envoyer au mode Expert\n            </button>\n\n            <button\n              onClick={() => setAnalysis(null)}\n              className=\"w-full py-3 bg-slate-900 text-white rounded-xl text-[10px] font-bold uppercase tracking-widest\"\n            >\n              Nouvelle Inspection\n            </button>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
  "apps/frontend/src/pages/Devis.tsx": "// apps/frontend/src/pages/Devis.tsx\nimport React, { useState, useRef, useEffect } from \"react\";\nimport { toast } from \"react-hot-toast\";\nimport {\n  Mic,\n  CloudUpload,\n  Loader2,\n  User,\n  Square,\n  Trash2,\n  FileText,\n} from \"lucide-react\";\nimport { useAuth } from \"../store/auth.store\";\nimport { ApiRequestError, toApiRequestError } from \"../utils/apiRequestError\";\n\n// ✅ AJOUT\nimport type { AiRunResponse } from \"../api/types\";\n\nconst API_URL = \"http://localhost:8080/ai\";\n\nexport default function Devis() {\n  const [isProcessing, setIsProcessing] = useState(false);\n  const [isRecording, setIsRecording] = useState(false);\n  const [analysisResult, setAnalysisResult] = useState<any>(null);\n  const fileInputRef = useRef<HTMLInputElement>(null);\n\n  // Refs pour le micro\n  const mediaRecorder = useRef<MediaRecorder | null>(null);\n  const audioChunks = useRef<Blob[]>([]);\n\n  const { accessToken } = useAuth();\n\n  // ✅ Anti multi-poll + cleanup\n  const pollIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);\n  const isPollingRef = useRef(false);\n\n  useEffect(() => {\n    return () => {\n      if (pollIntervalRef.current) {\n        clearInterval(pollIntervalRef.current);\n        pollIntervalRef.current = null;\n      }\n      isPollingRef.current = false;\n    };\n  }, []);\n\n  const clearPoll = () => {\n    if (pollIntervalRef.current) {\n      clearInterval(pollIntervalRef.current);\n      pollIntervalRef.current = null;\n    }\n    isPollingRef.current = false;\n  };\n\n  // --- 1. POLLING DU STATUT ---\n  const startPolling = (jobId: string) => {\n    // ✅ Stop ancien poll si existant\n    clearPoll();\n\n    // ✅ Empêcher multi-poll\n    if (isPollingRef.current) return;\n    isPollingRef.current = true;\n\n    // ✅ Backoff 429 : 1s → 2s → 4s → 8s → 10s (max)\n    let delayMs = 1000;\n    const maxDelayMs = 10000;\n\n    const tick = async () => {\n      try {\n        const response = await fetch(`${API_URL}/status/${jobId}`, {\n          headers: { Authorization: `Bearer ${accessToken}` },\n        });\n\n        if (!response.ok) {\n          throw await toApiRequestError(response);\n        }\n\n        const data = await response.json();\n\n        if (data.status === \"completed\") {\n          clearPoll();\n\n          let finalData = data.result;\n\n          // Nettoyage JSON si nécessaire\n          if (typeof finalData === \"string\") {\n            const match = finalData.match(/\\{[\\s\\S]*\\}/);\n            finalData = match ? JSON.parse(match[0]) : JSON.parse(finalData);\n          }\n\n          setAnalysisResult(finalData);\n          setIsProcessing(false);\n        } else if (data.status === \"failed\") {\n          clearPoll();\n          setIsProcessing(false);\n          toast.error(data.error || \"L'analyse a échoué.\");\n        }\n      } catch (e) {\n        const err = e as ApiRequestError;\n\n        // ✅ 429 backoff\n        if (err.code === \"too_many_requests\") {\n          clearPoll();\n          delayMs = Math.min(maxDelayMs, delayMs * 2);\n          isPollingRef.current = true;\n          pollIntervalRef.current = setInterval(tick, delayMs);\n          return;\n        }\n\n        clearPoll();\n        setIsProcessing(false);\n        toast.error(err.message || \"Erreur de suivi du job.\");\n      }\n    };\n\n    // Démarrage immédiat, puis interval\n    tick();\n    pollIntervalRef.current = setInterval(tick, delayMs);\n  };\n\n  // --- 2. LOGIQUE DU MICRO ---\n  const startRecording = async () => {\n    try {\n      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });\n      mediaRecorder.current = new MediaRecorder(stream);\n      audioChunks.current = [];\n\n      mediaRecorder.current.ondataavailable = (e) =>\n        audioChunks.current.push(e.data);\n      mediaRecorder.current.onstop = async () => {\n        const audioBlob = new Blob(audioChunks.current, { type: \"audio/mp3\" });\n        await sendToAI(audioBlob, \"vocal\");\n        stream.getTracks().forEach((track) => track.stop());\n      };\n\n      mediaRecorder.current.start();\n      setIsRecording(true);\n    } catch {\n      toast.error(\"Accès micro refusé ou non disponible.\");\n    }\n  };\n\n  const stopRecording = () => {\n    if (mediaRecorder.current && isRecording) {\n      mediaRecorder.current.stop();\n      setIsRecording(false);\n    }\n  };\n\n  // --- 3. ENVOI À L'IA (Image ou Audio) ---\n  const sendToAI = async (file: File | Blob, typeOverride?: string) => {\n    setIsProcessing(true);\n    setAnalysisResult(null);\n\n    // ✅ stop ancien poll si existant\n    clearPoll();\n\n    try {\n      const formData = new FormData();\n\n      formData.append(\n        \"file\",\n        file,\n        typeOverride === \"vocal\" ? \"capture.mp3\" : \"image.jpg\"\n      );\n\n      const finalType =\n        typeOverride || (file.type.startsWith(\"audio\") ? \"vocal\" : \"vision\");\n      formData.append(\"type\", finalType);\n\n      const response = await fetch(`${API_URL}/run`, {\n        method: \"POST\",\n        body: formData,\n        headers: { Authorization: `Bearer ${accessToken}` },\n      });\n\n      if (!response.ok) {\n        throw await toApiRequestError(response);\n      }\n\n      // ✅ MODIF: typer la réponse /ai/run\n      const data = (await response.json()) as AiRunResponse;\n      if (data.jobId) startPolling(data.jobId);\n    } catch (e) {\n      const err = e as ApiRequestError;\n\n      toast.error(err.message || \"Erreur de connexion.\");\n      setIsProcessing(false);\n      clearPoll();\n    }\n  };\n\n  return (\n    <div className=\"h-full max-w-md mx-auto flex flex-col gap-3 p-4\">\n      <input\n        type=\"file\"\n        ref={fileInputRef}\n        onChange={(e) => e.target.files?.[0] && sendToAI(e.target.files[0])}\n        className=\"hidden\"\n        accept=\"image/*,audio/*\"\n      />\n\n      {/* ZONE D'UPLOAD */}\n      <div className=\"bg-[var(--theme-card)] rounded-2xl p-4 border border-slate-100 shadow-sm shrink-0\">\n        <div className=\"flex items-center gap-2 mb-3\">\n          <span className=\"text-emerald-500 text-xs\">📂</span>\n          <span className=\"text-[9px] font-black text-slate-400 uppercase tracking-widest\">\n            Analyse de documents\n          </span>\n        </div>\n\n        <div\n          onClick={() => !isProcessing && fileInputRef.current?.click()}\n          className={`border-2 border-dashed rounded-xl py-6 flex flex-col items-center justify-center gap-1 transition-all cursor-pointer\n            ${\n              isProcessing\n                ? \"bg-[var(--theme-bg)] border-blue-200\"\n                : \"border-slate-100 hover:bg-[var(--theme-bg)] hover:border-slate-300\"\n            }\n          `}\n        >\n          {isProcessing ? (\n            <span className=\"text-[11px] font-medium text-blue-500 flex items-center gap-2\">\n              <Loader2 size={16} className=\"animate-spin\" /> Analyse en cours...\n            </span>\n          ) : (\n            <span className=\"text-[11px] font-medium italic text-slate-400 flex items-center gap-2\">\n              <CloudUpload size={16} /> Photo ou fichier audio\n            </span>\n          )}\n        </div>\n      </div>\n\n      {/* ZONE DE RÉSULTAT OU DESIGN VOCAL */}\n      <div className=\"flex-1 bg-[var(--theme-card)] rounded-[2rem] p-6 shadow-sm flex flex-col min-h-0 overflow-y-auto relative\">\n        {analysisResult ? (\n          <div className=\"space-y-6 animate-in slide-in-from-bottom-4 duration-500\">\n            <h2 className=\"text-sm font-black text-[var(--theme-text)] uppercase tracking-widest border-b pb-2\">\n              Analyse Terminée\n            </h2>\n\n            <div className=\"space-y-4\">\n              <div className=\"flex items-start gap-3\">\n                <div className=\"p-2 bg-blue-50 rounded-lg text-blue-500\">\n                  <User size={18} />\n                </div>\n                <div>\n                  <p className=\"text-[10px] font-bold text-slate-400 uppercase\">\n                    Client\n                  </p>\n                  <p className=\"font-bold text-slate-800\">\n                    {analysisResult.clientName || \"Non identifié\"}\n                  </p>\n                </div>\n              </div>\n\n              <div className=\"grid grid-cols-2 gap-3\">\n                <div className=\"p-3 bg-[var(--theme-bg)] rounded-xl\">\n                  <p className=\"text-[10px] font-bold text-slate-400 uppercase\">\n                    Total HT\n                  </p>\n                  <p className=\"text-lg font-black text-[var(--theme-text)]\">\n                    {analysisResult.totalHT || \"0\"} €\n                  </p>\n                </div>\n                <div className=\"p-3 bg-emerald-50 rounded-xl\">\n                  <p className=\"text-[10px] font-bold text-emerald-500 uppercase\">\n                    Total TTC\n                  </p>\n                  <p className=\"text-lg font-black text-emerald-600\">\n                    {analysisResult.totalTTC || \"0\"} €\n                  </p>\n                </div>\n              </div>\n\n              <div className=\"space-y-2\">\n                <p className=\"text-[10px] font-bold text-slate-400 uppercase\">\n                  Prestations\n                </p>\n                {analysisResult.items?.map((item: any, idx: number) => (\n                  <div\n                    key={idx}\n                    className=\"text-[11px] bg-[var(--theme-bg)] p-2 rounded-lg flex justify-between border border-slate-100\"\n                  >\n                    <span className=\"text-slate-600 font-medium\">\n                      {item.description}\n                    </span>\n                    <span className=\"font-bold text-[var(--theme-text)]\">\n                      {item.price}€\n                    </span>\n                  </div>\n                ))}\n              </div>\n            </div>\n\n            <button\n              onClick={() => setAnalysisResult(null)}\n              className=\"w-full py-3 bg-slate-900 text-white rounded-xl text-[11px] font-bold uppercase mt-4\"\n            >\n              Nouveau Devis\n            </button>\n          </div>\n        ) : (\n          <div className=\"h-full flex flex-col items-center justify-between py-4\">\n            <h2 className=\"text-lg font-black text-[var(--theme-text)] uppercase\">\n              Note Vocale\n            </h2>\n\n            <div className=\"flex flex-col items-center gap-6\">\n              <button\n                onClick={isRecording ? stopRecording : startRecording}\n                disabled={isProcessing}\n                className={`w-32 h-32 rounded-full flex items-center justify-center border-8 border-slate-50 shadow-2xl transition-all active:scale-95\n                  ${\n                    isRecording\n                      ? \"bg-red-500 text-white animate-pulse border-red-100\"\n                      : isProcessing\n                      ? \"bg-slate-100 text-slate-300\"\n                      : \"bg-blue-600 text-white hover:bg-blue-700\"\n                  }\n                `}\n              >\n                {isProcessing ? (\n                  <Loader2 size={48} className=\"animate-spin\" />\n                ) : isRecording ? (\n                  <Square size={48} fill=\"white\" />\n                ) : (\n                  <Mic size={48} />\n                )}\n              </button>\n\n              <div className=\"text-center\">\n                <p className=\"font-black text-[var(--theme-text)] text-[13px] uppercase\">\n                  {isRecording\n                    ? \"Enregistrement...\"\n                    : isProcessing\n                    ? \"Analyse en cours...\"\n                    : \"Appuyez pour parler\"}\n                </p>\n                <p className=\"text-[10px] text-slate-400 font-bold uppercase italic mt-1\">\n                  Dictez les travaux, l'IA s'occupe du reste\n                </p>\n              </div>\n            </div>\n\n            {/* BARRE D'ICÔNES CORRIGÉE */}\n            <div className=\"w-full pt-4 border-t border-slate-50 flex justify-around opacity-30\">\n              <div className=\"flex flex-col items-center gap-1\">\n                <User size={16} />\n                <span className=\"text-[7px] font-bold uppercase\">Client</span>\n              </div>\n              <div className=\"flex flex-col items-center gap-1\">\n                <FileText size={16} />\n                <span className=\"text-[7px] font-bold uppercase\">Devis</span>\n              </div>\n              <div className=\"flex flex-col items-center gap-1\">\n                <Trash2 size={16} />\n                <span className=\"text-[7px] font-bold uppercase\">Reset</span>\n              </div>\n            </div>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
  "apps/frontend/src/pages/Invoices.tsx": "// apps/frontend/src/pages/Invoices.tsx\nimport React, { useEffect, useMemo, useRef, useState } from \"react\";\nimport { Link, useNavigate } from \"react-router-dom\";\nimport { Plus, FileText, ArrowRight, Search } from \"lucide-react\";\nimport {\n  createInvoiceDraft,\n  listInvoices,\n  moneyCentsFromInvoice,\n  type Invoice,\n} from \"../services/invoices.api\";\n\nfunction formatEurFromCents(cents: number): string {\n  const euros = (Number.isFinite(cents) ? cents : 0) / 100;\n  return new Intl.NumberFormat(\"fr-FR\", {\n    style: \"currency\",\n    currency: \"EUR\",\n    maximumFractionDigits: 2,\n  }).format(euros);\n}\n\nfunction isoDatePlusDays(days: number): string {\n  const d = new Date();\n  d.setDate(d.getDate() + days);\n  return d.toISOString().slice(0, 10);\n}\n\nexport default function Invoices() {\n  const navigate = useNavigate();\n  const [items, setItems] = useState<Invoice[]>([]);\n  const [loading, setLoading] = useState(false);\n  const [q, setQ] = useState(\"\");\n  const fetchOnceRef = useRef(false);\n\n  const load = async () => {\n    setLoading(true);\n    try {\n      const data = await listInvoices();\n      // ✅ MODIF: normalisation defensive (évite crash si API renvoie autre chose)\n      setItems(Array.isArray(data) ? data : []);\n    } catch {\n      setItems([]);\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  useEffect(() => {\n    if (fetchOnceRef.current) return;\n    fetchOnceRef.current = true;\n    void load();\n  }, []);\n\n  const filtered = useMemo(() => {\n    const query = q.trim().toLowerCase();\n    if (!query) return items;\n\n    return items.filter((it) => {\n      const id = String(it.id ?? \"\").toLowerCase();\n      const cn = String(it.client_name ?? \"\").toLowerCase();\n      const st = String(it.status ?? \"\").toLowerCase();\n      return id.includes(query) || cn.includes(query) || st.includes(query);\n    });\n  }, [items, q]);\n\n  const onCreate = async () => {\n    setLoading(true);\n    try {\n      const inv = await createInvoiceDraft({\n        client_name: \"Nouveau client\",\n        client_email: null,\n        due_date: isoDatePlusDays(14),\n      });\n      navigate(`/invoices/${inv.id}`);\n    } catch {\n      // best-effort\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  return (\n    <div className=\"max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700\">\n      <div className=\"flex items-start justify-between gap-4\">\n        <div>\n          <h2 className=\"text-3xl font-extrabold text-[var(--theme-text)] tracking-tight\">\n            Factures\n          </h2>\n          <p className=\"text-slate-500 mt-1\">\n            Créez vos factures dans ArtisanPro, ajoutez les lignes, puis finalisez\n            (sync).\n          </p>\n        </div>\n\n        <button\n          onClick={onCreate}\n          disabled={loading}\n          className=\"inline-flex items-center gap-2 bg-slate-900 text-white px-4 py-3 rounded-2xl font-bold text-sm hover:bg-blue-600 transition-colors disabled:opacity-60\"\n        >\n          <Plus size={16} /> Nouvelle facture\n        </button>\n      </div>\n\n      <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n        <div className=\"p-4 border-b border-slate-50 flex items-center justify-between gap-3\">\n          <div className=\"flex items-center gap-2 w-full max-w-md bg-[var(--theme-bg)] rounded-2xl px-3 py-2 border border-slate-100\">\n            <Search size={16} className=\"text-slate-400\" />\n            <input\n              value={q}\n              onChange={(e) => setQ(e.target.value)}\n              placeholder=\"Rechercher (client, statut, id)…\"\n              className=\"w-full bg-transparent outline-none text-sm font-medium text-slate-700 placeholder:text-slate-400\"\n            />\n          </div>\n\n          <button\n            onClick={load}\n            disabled={loading}\n            className=\"text-sm font-bold text-slate-500 hover:text-[var(--theme-text)] disabled:opacity-60\"\n          >\n            Rafraîchir\n          </button>\n        </div>\n\n        <div className=\"divide-y divide-slate-50\">\n          {filtered.length > 0 ? (\n            filtered.map((it) => (\n              <Link\n                key={it.id}\n                to={`/invoices/${it.id}`}\n                className=\"p-4 flex items-center justify-between hover:bg-[var(--theme-bg)] transition-colors\"\n              >\n                <div className=\"flex items-center gap-4\">\n                  <div className=\"w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-slate-500\">\n                    <FileText size={18} />\n                  </div>\n                  <div>\n                    <p className=\"text-sm font-bold text-[var(--theme-text)]\">\n                      {it.client_name || \"Client\"}\n                    </p>\n                    <p className=\"text-xs text-slate-500 font-medium\">\n                      #{String(it.id).slice(0, 8)} •{\" \"}\n                      {String(it.status).toUpperCase()}\n                    </p>\n                  </div>\n                </div>\n\n                <div className=\"flex items-center gap-4\">\n                  <span className=\"text-sm font-black text-[var(--theme-text)]\">\n                    {formatEurFromCents(moneyCentsFromInvoice(it))}\n                  </span>\n                  <ArrowRight size={18} className=\"text-slate-400\" />\n                </div>\n              </Link>\n            ))\n          ) : (\n            <div className=\"p-8 text-sm text-slate-500 text-center\">\n              {loading ? \"Chargement…\" : \"Aucune facture.\"}\n            </div>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "apps/frontend/src/pages/InvoiceDetail.tsx": "// apps/frontend/src/pages/InvoiceDetail.tsx\nimport React, { useEffect, useMemo, useRef, useState } from \"react\";\nimport { Link, useNavigate, useParams } from \"react-router-dom\";\nimport { ArrowLeft, CheckCircle2, AlertTriangle } from \"lucide-react\";\nimport {\n  deleteInvoice,\n  deleteInvoiceLine,\n  finalizeInvoice,\n  getInvoice,\n  listInvoiceLines,\n  moneyCentsFromInvoice,\n  patchInvoice,\n  payInvoice,\n  type Invoice,\n  type InvoiceLine,\n} from \"../services/invoices.api\";\nimport {\n  getPennylaneInvoiceSyncEvents,\n  resyncPennylaneInvoice,\n  type PennylaneInvoiceSyncEvent,\n} from \"../services/integrations.api\";\nimport InvoiceEditor from \"../components//invoices/InvoiceEditor\";\nimport InvoiceLinesEditor from \"../components/invoices/InvoiceLinesEditor\";\n\nfunction formatEurFromCents(cents: number): string {\n  const euros = (Number.isFinite(cents) ? cents : 0) / 100;\n  return new Intl.NumberFormat(\"fr-FR\", {\n    style: \"currency\",\n    currency: \"EUR\",\n    maximumFractionDigits: 2,\n  }).format(euros);\n}\n\nexport default function InvoiceDetail() {\n  const { id } = useParams<{ id: string }>();\n  const invoiceId = String(id || \"\");\n  const navigate = useNavigate();\n\n  const [loading, setLoading] = useState(false);\n  const [resyncLoading, setResyncLoading] = useState(false);\n  const [syncEventsLoading, setSyncEventsLoading] = useState(false);\n  const [invoice, setInvoice] = useState<Invoice | null>(null);\n  const [lines, setLines] = useState<InvoiceLine[]>([]);\n  const [syncEvents, setSyncEvents] = useState<PennylaneInvoiceSyncEvent[]>([]);\n  const [error, setError] = useState<string | null>(null);\n\n  const fetchOnceRef = useRef(false);\n\n  const load = async () => {\n    if (!invoiceId) return;\n    setLoading(true);\n    setError(null);\n    try {\n      const inv = await getInvoice(invoiceId);\n      const lns = await listInvoiceLines(invoiceId);\n      setInvoice(inv);\n      setLines(lns);\n    } catch {\n      setError(\"Impossible de charger la facture.\");\n      setInvoice(null);\n      setLines([]);\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const loadSyncEvents = async () => {\n    if (!invoiceId) return;\n    setSyncEventsLoading(true);\n    try {\n      const events = await getPennylaneInvoiceSyncEvents(invoiceId);\n      setSyncEvents(events);\n    } catch {\n      setSyncEvents([]);\n    } finally {\n      setSyncEventsLoading(false);\n    }\n  };\n\n  useEffect(() => {\n    if (fetchOnceRef.current) return;\n    fetchOnceRef.current = true;\n    void load();\n    void loadSyncEvents();\n  }, [invoiceId]);\n\n  const totals = useMemo(() => {\n    const subtotal = lines.reduce((a, l) => a + (l.line_total_cents ?? 0), 0);\n    const tax = lines.reduce((a, l) => {\n      const rate = Number.isFinite(l.tax_rate) ? l.tax_rate : 0;\n      return a + Math.round((l.line_total_cents ?? 0) * (rate / 100));\n    }, 0);\n    const total = subtotal + tax;\n\n    return { subtotal, tax, total };\n  }, [lines]);\n\n  const canFinalize = useMemo(() => {\n    const st = String(invoice?.status ?? \"\").toLowerCase();\n    if (!invoice) return false;\n    if (st !== \"draft\" && st !== \"sent\") return false;\n    return lines.length > 0;\n  }, [invoice, lines.length]);\n\n  const canPay = useMemo(() => {\n    if (!invoice) return false;\n\n    const st = String(invoice.status ?? \"\").toLowerCase();\n    if (st === \"paid\" || st === \"canceled\") return false;\n\n    const emailOk =\n      !!invoice.client_email && String(invoice.client_email).trim().length > 0;\n    if (!emailOk) return false;\n\n    const amountCents = moneyCentsFromInvoice(invoice);\n    return Number.isFinite(amountCents) && amountCents > 0;\n  }, [invoice]);\n\n  const canResyncPennylane = useMemo(() => {\n    if (!invoice) return false;\n    const st = String(invoice.status ?? \"\").toLowerCase();\n    return st === \"sent\";\n  }, [invoice]);\n\n  const latestSyncEvent = useMemo(() => {\n    return syncEvents.length > 0 ? syncEvents[0] : null;\n  }, [syncEvents]);\n\n  const onSaveHeader = async (patch: {\n    client_name: string;\n    client_email: string | null;\n    due_date: string;\n    project_id: string | null;\n  }) => {\n    if (!invoice) return;\n    setLoading(true);\n    setError(null);\n    try {\n      const updated = await patchInvoice(invoice.id, patch);\n      setInvoice(updated);\n    } catch {\n      setError(\"Impossible d’enregistrer les modifications.\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const onFinalize = async () => {\n    if (!invoice) return;\n\n    if (lines.length === 0) {\n      setError(\"Ajoute au moins une ligne avant de finaliser.\");\n      return;\n    }\n\n    setLoading(true);\n    setError(null);\n\n    try {\n      const res = await finalizeInvoice(invoice.id);\n      setInvoice(res.invoice);\n      const lns = await listInvoiceLines(invoice.id);\n      setLines(lns);\n      await loadSyncEvents();\n    } catch {\n      setError(\"Finalisation impossible (vérifie lignes, permissions, backend).\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const onPay = async () => {\n    if (!invoice) return;\n\n    if (!invoice.client_email || String(invoice.client_email).trim().length === 0) {\n      setError(\"Ajoute un email client pour activer le paiement Stripe.\");\n      return;\n    }\n\n    const amountCents = moneyCentsFromInvoice(invoice);\n    if (!Number.isFinite(amountCents) || amountCents <= 0) {\n      setError(\"Le montant de la facture doit être supérieur à 0.\");\n      return;\n    }\n\n    setLoading(true);\n    setError(null);\n\n    try {\n      const res = await payInvoice(invoice.id);\n\n      const checkoutUrl = (res as any)?.checkoutUrl;\n      if (!checkoutUrl || typeof checkoutUrl !== \"string\") {\n        setError(\"Impossible de démarrer le paiement (URL Stripe manquante).\");\n        return;\n      }\n\n      window.location.href = checkoutUrl;\n    } catch {\n      setError(\"Impossible de démarrer le paiement (Stripe).\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const onResyncPennylane = async () => {\n    if (!invoice) return;\n\n    setResyncLoading(true);\n    setError(null);\n\n    try {\n      await resyncPennylaneInvoice(invoice.id);\n      await loadSyncEvents();\n    } catch {\n      setError(\"Impossible de relancer la synchronisation Pennylane.\");\n    } finally {\n      setResyncLoading(false);\n    }\n  };\n\n  const onDeleteInvoice = async () => {\n    if (!invoice) return;\n\n    const confirmed = window.confirm(\n      \"Supprimer cette facture ? Cette action est irréversible.\"\n    );\n    if (!confirmed) return;\n\n    setLoading(true);\n    setError(null);\n\n    try {\n      for (const line of lines) {\n        await deleteInvoiceLine(line.id);\n      }\n\n      await deleteInvoice(invoice.id);\n      navigate(\"/invoices\", { replace: true });\n    } catch {\n      setError(\"Impossible de supprimer la facture.\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const status = String(invoice?.status ?? \"\").toLowerCase();\n\n  return (\n    <div className=\"max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700\">\n      <div className=\"flex items-start justify-between gap-4\">\n        <div>\n          <Link\n            to=\"/invoices\"\n            className=\"inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-[var(--theme-text)]\"\n          >\n            <ArrowLeft size={16} /> Retour\n          </Link>\n\n          <h2 className=\"text-3xl font-extrabold text-[var(--theme-text)] tracking-tight mt-2\">\n            Facture\n          </h2>\n\n          <p className=\"text-slate-500 mt-1\">\n            {invoice ? `#${invoice.id.slice(0, 8)}` : \"Chargement…\"}\n          </p>\n        </div>\n\n        <div className=\"flex items-center gap-3\">\n          <button\n            onClick={() => navigate(\"/invoices\")}\n            className=\"hidden sm:inline-flex items-center gap-2 bg-[var(--theme-card)] border border-[var(--theme-border)] text-[var(--theme-text)] px-4 py-3 rounded-2xl font-bold text-sm hover:border-blue-200 hover:bg-blue-50/30 transition-colors\"\n          >\n            Liste\n          </button>\n\n          <button\n            onClick={onDeleteInvoice}\n            disabled={loading}\n            className=\"hidden sm:inline-flex items-center gap-2 bg-[var(--theme-card)] border border-red-200 text-red-700 px-4 py-3 rounded-2xl font-bold text-sm hover:bg-red-50 transition-colors disabled:opacity-60\"\n          >\n            Supprimer\n          </button>\n\n          <button\n            onClick={onResyncPennylane}\n            disabled={!canResyncPennylane || resyncLoading || loading}\n            className=\"inline-flex items-center gap-2 bg-[var(--theme-card)] border border-[var(--theme-border)] text-[var(--theme-text)] px-4 py-3 rounded-2xl font-bold text-sm hover:border-indigo-200 hover:bg-indigo-50/30 transition-colors disabled:opacity-60\"\n          >\n            Resync Pennylane\n          </button>\n\n          <button\n            onClick={onPay}\n            disabled={!canPay || loading}\n            className=\"inline-flex items-center gap-2 bg-[var(--theme-card)] border border-[var(--theme-border)] text-[var(--theme-text)] px-4 py-3 rounded-2xl font-bold text-sm hover:border-emerald-200 hover:bg-emerald-50/30 transition-colors disabled:opacity-60\"\n          >\n            Payer la facture\n          </button>\n\n          <button\n            onClick={onFinalize}\n            disabled={!canFinalize || loading}\n            className=\"inline-flex items-center gap-2 bg-slate-900 text-white px-4 py-3 rounded-2xl font-bold text-sm hover:bg-blue-600 transition-colors disabled:opacity-60\"\n          >\n            <CheckCircle2 size={16} /> Finaliser & Sync\n          </button>\n        </div>\n      </div>\n\n      {error ? (\n        <div className=\"bg-[var(--theme-card)] border border-red-100 rounded-2xl p-4 text-sm text-red-700 flex items-start gap-3\">\n          <AlertTriangle size={18} className=\"mt-0.5\" />\n          <div>{error}</div>\n        </div>\n      ) : null}\n\n      <div className=\"grid grid-cols-1 lg:grid-cols-3 gap-6\">\n        <div className=\"lg:col-span-2 space-y-6\">\n          <InvoiceEditor\n            loading={loading}\n            invoice={invoice}\n            onSave={onSaveHeader}\n          />\n\n          <InvoiceLinesEditor\n            loading={loading}\n            invoiceId={invoiceId}\n            lines={lines}\n            onChangeLines={setLines}\n            onReload={load}\n          />\n        </div>\n\n        <div className=\"space-y-6\">\n          <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n            <div className=\"p-6 border-b border-slate-50\">\n              <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">Totaux</h3>\n              <p className=\"text-[11px] text-slate-500 font-medium mt-1\">\n                Calculs en centimes (MVP).\n              </p>\n            </div>\n\n            <div className=\"p-6 space-y-3\">\n              <Row label=\"Sous-total (HT)\" value={formatEurFromCents(totals.subtotal)} />\n              <Row label=\"TVA (estimée)\" value={formatEurFromCents(totals.tax)} />\n              <div className=\"h-px bg-slate-100 my-2\" />\n              <Row\n                label=\"Total (TTC)\"\n                value={formatEurFromCents(totals.total)}\n                strong\n              />\n\n              <div className=\"mt-4 text-xs text-slate-400 font-medium\">\n                Statut:{\" \"}\n                <span className=\"font-black text-slate-700\">\n                  {status ? status.toUpperCase() : \"—\"}\n                </span>\n              </div>\n\n              <div className=\"mt-4 text-xs text-slate-400 font-medium\">\n                Total enregistré (invoice):{\" \"}\n                <span className=\"font-black text-slate-700\">\n                  {invoice ? formatEurFromCents(moneyCentsFromInvoice(invoice)) : \"—\"}\n                </span>\n              </div>\n\n              <div className=\"mt-4 text-xs text-slate-400 font-medium\">\n                Chantier lié:{\" \"}\n                <span className=\"font-black text-slate-700\">\n                  {invoice?.project_id ? invoice.project_id.slice(0, 8) : \"Aucun\"}\n                </span>\n              </div>\n\n              <div className=\"mt-5 text-xs text-slate-400 font-medium\">\n                Pour déclencher la sync : au moins 1 ligne + finalisation.\n              </div>\n            </div>\n          </div>\n\n          <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n            <div className=\"p-6 border-b border-slate-50\">\n              <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">Sync Pennylane</h3>\n            </div>\n\n            <div className=\"p-6 space-y-3 text-sm text-slate-600\">\n              {syncEventsLoading ? (\n                <div>Chargement des événements…</div>\n              ) : latestSyncEvent ? (\n                <>\n                  <div className=\"flex items-center justify-between\">\n                    <span>Dernier statut</span>\n                    <span\n                      className={`font-black uppercase tracking-widest text-xs ${\n                        latestSyncEvent.status === \"success\"\n                          ? \"text-emerald-600\"\n                          : \"text-red-600\"\n                      }`}\n                    >\n                      {latestSyncEvent.status}\n                    </span>\n                  </div>\n\n                  <div className=\"flex items-center justify-between\">\n                    <span>Dernière tentative</span>\n                    <span className=\"font-bold text-[var(--theme-text)]\">\n                      {new Date(latestSyncEvent.created_at).toLocaleString(\"fr-FR\")}\n                    </span>\n                  </div>\n\n                  <div className=\"pt-2 text-xs text-slate-500\">\n                    Message : {latestSyncEvent.message ?? \"—\"}\n                  </div>\n                </>\n              ) : (\n                <div>Aucun événement de synchronisation pour cette facture.</div>\n              )}\n            </div>\n          </div>\n\n          <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n            <div className=\"p-6 border-b border-slate-50\">\n              <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">Recommandations</h3>\n            </div>\n            <div className=\"p-6 space-y-2 text-sm text-slate-600\">\n              <Bullet>Créer en draft → lignes → finaliser.</Bullet>\n              <Bullet>Rattacher la facture à un chantier pour alimenter les analytics.</Bullet>\n              <Bullet>Garder les montants en centimes partout (cohérence).</Bullet>\n              <Bullet>Si tu modifies des lignes après “sent”, refais “Finaliser & Sync” pour resync.</Bullet>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction Row({\n  label,\n  value,\n  strong,\n}: {\n  label: string;\n  value: string;\n  strong?: boolean;\n}) {\n  return (\n    <div className=\"flex items-center justify-between\">\n      <div className={`text-sm ${strong ? \"font-bold text-[var(--theme-text)]\" : \"text-slate-600\"}`}>\n        {label}\n      </div>\n      <div\n        className={`text-sm ${strong ? \"font-black text-[var(--theme-text)]\" : \"font-bold text-[var(--theme-text)]\"}`}\n      >\n        {value}\n      </div>\n    </div>\n  );\n}\n\nfunction Bullet({ children }: { children: React.ReactNode }) {\n  return (\n    <div className=\"flex gap-3\">\n      <span className=\"mt-2 w-1.5 h-1.5 rounded-full bg-slate-300\" />\n      <div>{children}</div>\n    </div>\n  );\n}\n",
  "apps/frontend/src/pages/Facture.tsx": "// apps/frontend/src/pages/Facture.tsx\nimport { useState, useMemo } from 'react';\nimport { \n  Search, \n  FileCheck, \n  Send, \n  AlertTriangle, \n  CheckCircle2, \n  Clock,\n  Filter,\n  History,\n  TrendingUp,\n  ReceiptEuro\n} from 'lucide-react';\n\ninterface FactureItem {\n  id: string;\n  client: string;\n  echeance: string;\n  montant: string;\n  statut: 'PAYÉ' | 'RETARD' | 'ATTENTE';\n  nbRelances: number;\n}\n\nconst MOCK_FACTURES: FactureItem[] = [\n  { id: 'FAC-2026-001', client: 'Jean Dupont', echeance: '15/02/2026', montant: '1,250.00€', statut: 'PAYÉ', nbRelances: 0 },\n  { id: 'FAC-2026-002', client: 'Entreprise Leroy', echeance: '05/02/2026', montant: '4,840.00€', statut: 'RETARD', nbRelances: 2 },\n  { id: 'FAC-2026-003', client: 'Boulangerie Soleil', echeance: '25/02/2026', montant: '2,100.00€', statut: 'ATTENTE', nbRelances: 0 },\n  { id: 'FAC-2026-004', client: 'Marc Morel', echeance: '10/02/2026', montant: '550.00€', statut: 'RETARD', nbRelances: 1 },\n];\n\n// Changement du nom de la fonction en \"Compta\" pour correspondre au routeur\nexport default function Compta() {\n  const [searchTerm, setSearchTerm] = useState('');\n\n  const filteredFactures = useMemo(() => {\n    return MOCK_FACTURES.filter(item => \n      item.client.toLowerCase().includes(searchTerm.toLowerCase()) ||\n      item.id.toLowerCase().includes(searchTerm.toLowerCase())\n    );\n  }, [searchTerm]);\n\n  return (\n    <div className=\"max-w-6xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-10\">\n      \n      {/* HEADER AVEC STATS RAPIDES */}\n      <div className=\"flex flex-col md:flex-row md:items-end justify-between gap-4 mb-8\">\n        <div>\n          <div className=\"flex items-center gap-2 mb-1\">\n            <span className=\"bg-blue-600 p-1.5 rounded-lg text-white\">\n                <ReceiptEuro size={16} />\n            </span>\n            <span className=\"text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]\">Finance & Gestion</span>\n          </div>\n          <h2 className=\"text-3xl font-extrabold text-[var(--theme-text)] tracking-tight\">Comptabilité</h2>\n          <p className=\"text-slate-500 mt-1 text-sm font-medium italic\">Suivi des encaissements et relances automatiques.</p>\n        </div>\n        \n        <div className=\"flex gap-3\">\n            <div className=\"bg-[var(--theme-card)] p-4 rounded-2xl border border-slate-100 shadow-sm min-w-[140px]\">\n                <p className=\"text-[9px] font-black text-slate-400 uppercase mb-1\">Total Encaissé</p>\n                <div className=\"flex items-center gap-2 text-emerald-600\">\n                    <TrendingUp size={14} />\n                    <p className=\"text-lg font-black\">8 190€</p>\n                </div>\n            </div>\n            <div className=\"bg-[var(--theme-card)] p-4 rounded-2xl border border-slate-100 shadow-sm min-w-[140px]\">\n                <p className=\"text-[9px] font-black text-slate-400 uppercase mb-1\">Impayés</p>\n                <div className=\"flex items-center gap-2 text-red-500\">\n                    <AlertTriangle size={14} />\n                    <p className=\"text-lg font-black\">5 390€</p>\n                </div>\n            </div>\n        </div>\n      </div>\n\n      {/* BARRE DE RECHERCHE */}\n      <div className=\"flex flex-col md:flex-row gap-4 items-center justify-between bg-[var(--theme-card)] p-3 rounded-2xl border border-slate-100 shadow-sm\">\n        <div className=\"relative flex-1 w-full\">\n          <Search className=\"absolute left-4 top-1/2 -translate-y-1/2 text-slate-400\" size={18} />\n          <input \n            type=\"text\" \n            placeholder=\"Rechercher un client ou une facture...\"\n            className=\"w-full pl-12 pr-4 py-3 bg-[var(--theme-bg)] border-none rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm font-medium\"\n            value={searchTerm}\n            onChange={(e) => setSearchTerm(e.target.value)}\n          />\n        </div>\n        <button className=\"flex items-center gap-2 px-5 py-3 bg-[var(--theme-card)] border border-[var(--theme-border)] rounded-xl text-slate-600 font-bold hover:bg-[var(--theme-bg)] transition-colors text-xs uppercase tracking-widest\">\n          <Filter size={16} /> Filtres\n        </button>\n      </div>\n\n      {/* TABLEAU DES FACTURES */}\n      <div className=\"bg-[var(--theme-card)] rounded-[2rem] shadow-xl shadow-slate-200/40 border border-slate-100 overflow-hidden\">\n        <div className=\"overflow-x-auto\">\n          <table className=\"w-full text-left border-collapse\">\n            <thead>\n              <tr className=\"bg-[var(--theme-bg)]/50 border-b border-slate-100\">\n                <th className=\"px-6 py-5 text-[10px] uppercase tracking-widest text-slate-400 font-black\">Référence</th>\n                <th className=\"px-6 py-5 text-[10px] uppercase tracking-widest text-slate-400 font-black\">Client</th>\n                <th className=\"px-6 py-5 text-[10px] uppercase tracking-widest text-slate-400 font-black\">Échéance</th>\n                <th className=\"px-6 py-5 text-[10px] uppercase tracking-widest text-slate-400 font-black\">Statut</th>\n                <th className=\"px-6 py-5 text-[10px] uppercase tracking-widest text-slate-400 font-black text-right\">Montant</th>\n                <th className=\"px-6 py-5\"></th>\n              </tr>\n            </thead>\n            <tbody className=\"divide-y divide-slate-50\">\n              {filteredFactures.map((fac) => (\n                <tr key={fac.id} className=\"hover:bg-[var(--theme-bg)]/40 transition-colors group\">\n                  <td className=\"px-6 py-5\">\n                    <div className=\"flex items-center gap-3\">\n                      <div className=\"w-9 h-9 bg-slate-100 text-slate-400 group-hover:bg-blue-50 group-hover:text-blue-600 rounded-xl flex items-center justify-center transition-colors\">\n                        <FileCheck size={18} />\n                      </div>\n                      <span className=\"font-mono text-xs font-bold text-slate-600\">{fac.id}</span>\n                    </div>\n                  </td>\n                  <td className=\"px-6 py-5 font-bold text-[var(--theme-text)]\">{fac.client}</td>\n                  <td className=\"px-6 py-5 text-slate-500 text-xs font-medium\">{fac.echeance}</td>\n                  <td className=\"px-6 py-5\">\n                    <StatutFacture statut={fac.statut} />\n                  </td>\n                  <td className=\"px-6 py-5 font-black text-[var(--theme-text)] text-right\">{fac.montant}</td>\n                  <td className=\"px-6 py-5\">\n                    <div className=\"flex items-center justify-end gap-2\">\n                      {fac.statut === 'RETARD' && (\n                        <button className=\"flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-tighter hover:bg-blue-600 transition-all shadow-sm\">\n                          <Send size={12} /> Relance IA\n                        </button>\n                      )}\n                      <button className=\"p-2 text-slate-300 hover:text-slate-600 rounded-lg transition-all\">\n                        <History size={18} />\n                      </button>\n                    </div>\n                  </td>\n                </tr>\n              ))}\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction StatutFacture({ statut }: { statut: FactureItem['statut'] }) {\n  const configs = {\n    'PAYÉ': { style: 'bg-emerald-50 text-emerald-700 border-emerald-100', icon: <CheckCircle2 size={12} />, label: 'PAYÉ' },\n    'RETARD': { style: 'bg-red-50 text-red-700 border-red-100', icon: <AlertTriangle size={12} />, label: 'IMPAYÉ' },\n    'ATTENTE': { style: 'bg-slate-100 text-slate-600 border-[var(--theme-border)]', icon: <Clock size={12} />, label: 'ATTENTE' }\n  };\n  const current = configs[statut];\n  return (\n    <span className={`flex items-center gap-1.5 w-fit px-3 py-1.5 rounded-full text-[9px] font-black tracking-widest border ${current.style}`}>\n      {current.icon} {current.label}\n    </span>\n  );\n}\n",
  "apps/frontend/src/pages/DashboardRevenue.tsx": "// apps/frontend/src/pages/DashboardRevenue.tsx\nimport React, { useEffect, useMemo, useRef, useState } from \"react\";\nimport { ArrowLeft, TrendingUp } from \"lucide-react\";\nimport { Link } from \"react-router-dom\";\nimport { fetchWithAuth } from \"../auth/fetchWithAuth\";\nimport { useComptaReportStore } from \"../store/comptaReport.store\";\n\ntype DashboardResponse = {\n  kpis?: {\n    revenue?: { paidAllTimeCents: number; paidMonthCents: number };\n  };\n};\n\ntype InvoiceRow = {\n  id: string;\n  client_name: string;\n  status: string;\n  created_at: string;\n  total_amount_cents?: number | null;\n  total_amount?: number | null;\n};\n\nfunction formatEurFromCents(cents: number): string {\n  const euros = (Number.isFinite(cents) ? cents : 0) / 100;\n  return new Intl.NumberFormat(\"fr-FR\", {\n    style: \"currency\",\n    currency: \"EUR\",\n    maximumFractionDigits: 2,\n  }).format(euros);\n}\n\nfunction formatEur(value: number): string {\n  return new Intl.NumberFormat(\"fr-FR\", {\n    style: \"currency\",\n    currency: \"EUR\",\n    maximumFractionDigits: 2,\n  }).format(Number.isFinite(value) ? value : 0);\n}\n\nfunction startOfCurrentMonthIso(): string {\n  const now = new Date();\n  const d = new Date(now);\n  d.setDate(1);\n  d.setHours(0, 0, 0, 0);\n  return d.toISOString();\n}\n\nfunction invoiceAmountCents(inv: InvoiceRow): number {\n  if (typeof inv.total_amount_cents === \"number\") return inv.total_amount_cents;\n  if (typeof inv.total_amount === \"number\") return Math.round(inv.total_amount * 100);\n  return 0;\n}\n\nexport default function DashboardRevenue() {\n  const report = useComptaReportStore((s) => s.report);\n\n  const [loading, setLoading] = useState(false);\n  const [kpis, setKpis] = useState<DashboardResponse[\"kpis\"] | null>(null);\n  const [invoices, setInvoices] = useState<InvoiceRow[]>([]);\n  const fetchOnceRef = useRef(false);\n\n  useEffect(() => {\n    if (fetchOnceRef.current) return;\n    fetchOnceRef.current = true;\n\n    let cancelled = false;\n    setLoading(true);\n\n    (async () => {\n      try {\n        const dash = await fetchWithAuth<DashboardResponse>(\"/dashboard\", {\n          method: \"GET\",\n        });\n\n        const inv = await fetchWithAuth<unknown>(\"/invoices\", { method: \"GET\" });\n\n        if (cancelled) return;\n\n        setKpis(dash?.kpis ?? null);\n        setInvoices((Array.isArray(inv) ? (inv as InvoiceRow[]) : []) ?? []);\n      } catch {\n        if (!cancelled) {\n          setKpis(null);\n          setInvoices([]);\n        }\n      } finally {\n        if (!cancelled) setLoading(false);\n      }\n    })();\n\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n\n  const monthStartIso = useMemo(() => startOfCurrentMonthIso(), []);\n\n  const paidMonth = useMemo(() => {\n    return invoices\n      .filter((i) => String(i.status).toLowerCase() === \"paid\")\n      .filter((i) => new Date(i.created_at).toISOString() >= monthStartIso)\n      .sort((a, b) => b.created_at.localeCompare(a.created_at));\n  }, [invoices, monthStartIso]);\n\n  const paidMonthTotalCents = useMemo(() => {\n    return paidMonth.reduce((acc, it) => acc + invoiceAmountCents(it), 0);\n  }, [paidMonth]);\n\n  const hasComptaReport = !!report;\n  const recettesHT = report?.totals?.recettesHT ?? 0;\n  const recettesTTC = report?.totals?.recettesTTC ?? 0;\n  const parMois = report?.breakdown?.parMois ?? [];\n  const topRecettes = report?.breakdown?.topRecettes ?? [];\n\n  const paidAllTimeCents = kpis?.revenue?.paidAllTimeCents ?? 0;\n  const paidMonthCents = kpis?.revenue?.paidMonthCents ?? paidMonthTotalCents;\n\n  const analysis = useMemo(() => {\n    if (hasComptaReport) {\n      return {\n        summary: `Recettes issues de l’analyse compta : ${formatEur(\n          recettesTTC\n        )} TTC pour ${formatEur(recettesHT)} HT.`,\n        actions: [\n          \"Comparer les recettes du mois avec les dépenses pour suivre la marge réelle.\",\n          \"Vérifier les mois les plus faibles pour anticiper la trésorerie.\",\n          \"Rattacher les recettes aux chantiers pour une lecture par activité.\",\n        ],\n      };\n    }\n\n    if (paidMonth.length === 0) {\n      return {\n        summary: \"Aucun encaissement enregistré ce mois-ci.\",\n        actions: [\n          \"Vérifie que les factures payées sont bien passées au statut “paid”.\",\n          \"Active des relances automatiques sur les factures “sent/overdue”.\",\n        ],\n      };\n    }\n\n    return {\n      summary: `Encaissements du mois: ${formatEurFromCents(\n        paidMonthCents\n      )} sur ${paidMonth.length} facture(s).`,\n      actions: [\n        \"Standardiser le process: facture → sent → paid (éviter les statuts incohérents).\",\n        \"Suivre le délai moyen de paiement (objectif: réduire les retards).\",\n        \"Ajouter un lien facture → chantier pour analyser le CA par chantier.\",\n      ],\n    };\n  }, [hasComptaReport, recettesTTC, recettesHT, paidMonth.length, paidMonthCents]);\n\n  return (\n    <div className=\"max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700\">\n      <div className=\"flex items-start justify-between gap-4\">\n        <div>\n          <div className=\"flex items-center gap-3\">\n            <Link\n              to=\"/dashboard\"\n              className=\"inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-[var(--theme-text)]\"\n            >\n              <ArrowLeft size={16} /> Retour\n            </Link>\n          </div>\n          <h2 className=\"text-3xl font-extrabold text-[var(--theme-text)] tracking-tight mt-2\">\n            Chiffre d&apos;affaires\n          </h2>\n          <p className=\"text-slate-500 mt-1\">\n            Analyse structurée basée sur vos données comptables.\n          </p>\n        </div>\n\n        <div className=\"hidden sm:flex items-center gap-2 bg-[var(--theme-card)] border border-slate-100 rounded-2xl px-4 py-3 shadow-sm\">\n          <TrendingUp className=\"text-emerald-500\" size={18} />\n          <span className=\"text-sm font-black text-[var(--theme-text)]\">\n            {loading\n              ? \"…\"\n              : hasComptaReport\n              ? formatEur(recettesTTC)\n              : formatEurFromCents(paidMonthCents)}\n          </span>\n          <span className=\"text-xs font-bold text-slate-400\">\n            {hasComptaReport ? \"analyse compta\" : \"mois en cours\"}\n          </span>\n        </div>\n      </div>\n\n      <div className=\"grid grid-cols-1 lg:grid-cols-3 gap-6\">\n        <KpiCard\n          label={hasComptaReport ? \"Recettes HT\" : \"Encaissements mois\"}\n          value={\n            loading\n              ? \"…\"\n              : hasComptaReport\n              ? formatEur(recettesHT)\n              : formatEurFromCents(paidMonthCents)\n          }\n          hint={\n            hasComptaReport\n              ? \"Issu de l’analyse compta.\"\n              : \"Basé sur les factures au statut paid.\"\n          }\n        />\n        <KpiCard\n          label={hasComptaReport ? \"Recettes TTC\" : \"Encaissements total\"}\n          value={\n            loading\n              ? \"…\"\n              : hasComptaReport\n              ? formatEur(recettesTTC)\n              : formatEurFromCents(paidAllTimeCents)\n          }\n          hint={\n            hasComptaReport\n              ? \"Synthèse globale de l’analyse.\"\n              : \"Historique complet.\"\n          }\n        />\n        <KpiCard\n          label={hasComptaReport ? \"Nb. mois analysés\" : \"Nb. factures payées (mois)\"}\n          value={loading ? \"…\" : hasComptaReport ? String(parMois.length) : String(paidMonth.length)}\n          hint={\n            hasComptaReport\n              ? \"Périodes détectées dans le fichier.\"\n              : \"Nombre de factures marked paid ce mois-ci.\"\n          }\n        />\n      </div>\n\n      <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-8\">\n        <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n          <div className=\"p-6 border-b border-slate-50\">\n            <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">Analyse & optimisation</h3>\n            <p className=\"text-[11px] text-slate-500 font-medium mt-1\">\n              Recommandations pragmatiques.\n            </p>\n          </div>\n\n          <div className=\"p-6 space-y-4\">\n            <p className=\"text-sm font-medium text-slate-700\">{analysis.summary}</p>\n            <ul className=\"space-y-2\">\n              {analysis.actions.map((a) => (\n                <li key={a} className=\"text-sm text-slate-600 flex gap-3\">\n                  <span className=\"mt-1.5 w-1.5 h-1.5 rounded-full bg-slate-300\" />\n                  <span>{a}</span>\n                </li>\n              ))}\n            </ul>\n          </div>\n        </div>\n\n        <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n          <div className=\"p-6 border-b border-slate-50 flex items-center justify-between\">\n            <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">\n              {hasComptaReport ? \"Top recettes\" : \"Factures payées (mois)\"}\n            </h3>\n            <span className=\"text-[10px] font-black uppercase tracking-widest text-slate-400\">\n              {loading\n                ? \"…\"\n                : hasComptaReport\n                ? `${topRecettes.length} éléments`\n                : `${paidMonth.length} éléments`}\n            </span>\n          </div>\n\n          <div className=\"divide-y divide-slate-50\">\n            {hasComptaReport ? (\n              topRecettes.length > 0 ? (\n                topRecettes.slice(0, 10).map((it) => (\n                  <div key={it.label} className=\"p-4 flex items-center justify-between\">\n                    <div>\n                      <p className=\"text-sm font-bold text-[var(--theme-text)]\">{it.label}</p>\n                      <p className=\"text-xs text-slate-500 font-medium\">\n                        {it.count} occurrence(s)\n                      </p>\n                    </div>\n                    <span className=\"text-sm font-black text-[var(--theme-text)]\">\n                      {formatEur(it.amountHT)}\n                    </span>\n                  </div>\n                ))\n              ) : (\n                <div className=\"p-6 text-sm text-slate-500\">Aucune recette détectée.</div>\n              )\n            ) : paidMonth.length > 0 ? (\n              paidMonth.slice(0, 10).map((it) => (\n                <div key={it.id} className=\"p-4 flex items-center justify-between\">\n                  <div>\n                    <p className=\"text-sm font-bold text-[var(--theme-text)]\">{it.client_name}</p>\n                    <p className=\"text-xs text-slate-500 font-medium\">#{it.id.slice(0, 8)}</p>\n                  </div>\n                  <span className=\"text-sm font-black text-[var(--theme-text)]\">\n                    {formatEurFromCents(invoiceAmountCents(it))}\n                  </span>\n                </div>\n              ))\n            ) : (\n              <div className=\"p-6 text-sm text-slate-500\">Aucune facture payée ce mois.</div>\n            )}\n          </div>\n\n          <div className=\"p-4 bg-[var(--theme-bg)]/50 text-center\">\n            <Link\n              to=\"/dashboard\"\n              className=\"text-xs font-bold text-slate-400 hover:text-blue-600 uppercase tracking-widest\"\n            >\n              Retour au dashboard\n            </Link>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction KpiCard({ label, value, hint }: any) {\n  return (\n    <div className=\"bg-[var(--theme-card)] p-6 rounded-3xl border border-slate-100 shadow-sm\">\n      <p className=\"text-slate-500 text-sm font-medium\">{label}</p>\n      <div className=\"text-2xl font-black text-[var(--theme-text)] mt-1\">{value}</div>\n      <p className=\"text-[11px] text-slate-400 font-medium mt-2\">{hint}</p>\n    </div>\n  );\n}\n",
  "apps/frontend/src/pages/DashboardUnpaid.tsx": "// apps/frontend/src/pages/DashboardUnpaid.tsx\nimport React, { useEffect, useMemo, useRef, useState } from \"react\";\nimport { AlertTriangle, ArrowLeft, MoreHorizontal } from \"lucide-react\";\nimport { Link } from \"react-router-dom\";\nimport { fetchWithAuth } from \"../auth/fetchWithAuth\";\nimport { useComptaReportStore } from \"../store/comptaReport.store\";\n\ntype DashboardResponse = {\n  kpis?: {\n    invoices?: {\n      unpaidCount: number;\n      unpaidTotalCents: number;\n      overdueCount: number;\n      overdueTotalCents: number;\n      preview: Array<{\n        id: string;\n        client: string;\n        totalAmountCents: number;\n        dueDate: string;\n        status: string;\n        daysLate: number;\n      }>;\n    };\n  };\n};\n\ntype InvoiceRow = {\n  id: string;\n  client_name: string;\n  status: string;\n  due_date: string;\n  total_amount_cents?: number | null;\n  total_amount?: number | null;\n};\n\nfunction formatEurFromCents(cents: number): string {\n  const euros = (Number.isFinite(cents) ? cents : 0) / 100;\n  return new Intl.NumberFormat(\"fr-FR\", {\n    style: \"currency\",\n    currency: \"EUR\",\n    maximumFractionDigits: 2,\n  }).format(euros);\n}\n\nfunction formatEur(value: number): string {\n  return new Intl.NumberFormat(\"fr-FR\", {\n    style: \"currency\",\n    currency: \"EUR\",\n    maximumFractionDigits: 2,\n  }).format(Number.isFinite(value) ? value : 0);\n}\n\nfunction formatDateFr(iso: string): string {\n  const d = new Date(iso);\n  if (Number.isNaN(d.getTime())) return iso;\n  return new Intl.DateTimeFormat(\"fr-FR\", {\n    day: \"2-digit\",\n    month: \"2-digit\",\n    year: \"numeric\",\n  }).format(d);\n}\n\nfunction invoiceAmountCents(inv: InvoiceRow): number {\n  if (typeof inv.total_amount_cents === \"number\") return inv.total_amount_cents;\n  if (typeof inv.total_amount === \"number\") return Math.round(inv.total_amount * 100);\n  return 0;\n}\n\nexport default function DashboardUnpaid() {\n  const report = useComptaReportStore((s) => s.report);\n\n  const [loading, setLoading] = useState(false);\n  const [kpis, setKpis] = useState<DashboardResponse[\"kpis\"] | null>(null);\n  const [invoices, setInvoices] = useState<InvoiceRow[]>([]);\n  const [menuOpen, setMenuOpen] = useState(false);\n  const fetchOnceRef = useRef(false);\n\n  useEffect(() => {\n    if (fetchOnceRef.current) return;\n    fetchOnceRef.current = true;\n\n    let cancelled = false;\n    setLoading(true);\n\n    (async () => {\n      try {\n        const dash = await fetchWithAuth<DashboardResponse>(\"/dashboard\", {\n          method: \"GET\",\n        });\n        const inv = await fetchWithAuth<unknown>(\"/invoices\", { method: \"GET\" });\n\n        if (cancelled) return;\n        setKpis(dash?.kpis ?? null);\n        setInvoices((Array.isArray(inv) ? (inv as InvoiceRow[]) : []) ?? []);\n      } catch {\n        if (!cancelled) {\n          setKpis(null);\n          setInvoices([]);\n        }\n      } finally {\n        if (!cancelled) setLoading(false);\n      }\n    })();\n\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n\n  const unpaidStatuses = useMemo(() => new Set([\"sent\", \"overdue\"]), []);\n  const unpaid = useMemo(() => {\n    return invoices\n      .filter((i) => unpaidStatuses.has(String(i.status).toLowerCase()))\n      .sort((a, b) => {\n        const ad = new Date(a.due_date).getTime();\n        const bd = new Date(b.due_date).getTime();\n        if (ad !== bd) return ad - bd;\n        return invoiceAmountCents(b) - invoiceAmountCents(a);\n      });\n  }, [invoices, unpaidStatuses]);\n\n  const overdue = useMemo(() => {\n    const now = Date.now();\n    return unpaid.filter((i) => new Date(i.due_date).getTime() < now);\n  }, [unpaid]);\n\n  const hasComptaReport = !!report;\n  const resultatNet = report?.totals?.resultatNet ?? 0;\n  const anomalies = report?.anomalies ?? [];\n  const criticalAnomalies = anomalies.filter((a) => a.severity === \"critical\");\n  const warnAnomalies = anomalies.filter((a) => a.severity === \"warn\");\n\n  const unpaidTotalCents =\n    kpis?.invoices?.unpaidTotalCents ??\n    unpaid.reduce((a, it) => a + invoiceAmountCents(it), 0);\n\n  const overdueTotalCents =\n    kpis?.invoices?.overdueTotalCents ??\n    overdue.reduce((a, it) => a + invoiceAmountCents(it), 0);\n\n  const unpaidCount = kpis?.invoices?.unpaidCount ?? unpaid.length;\n  const overdueCount = kpis?.invoices?.overdueCount ?? overdue.length;\n  const preview = kpis?.invoices?.preview ?? [];\n\n  const recommendations = useMemo(() => {\n    if (hasComptaReport) {\n      const actions: string[] = [];\n\n      if (resultatNet < 0) {\n        actions.push(\"Le résultat net est négatif : réduire les charges non essentielles en priorité.\");\n      }\n\n      if (criticalAnomalies.length > 0) {\n        actions.push(\"Traiter immédiatement les anomalies critiques détectées par l’analyse IA.\");\n      }\n\n      if (warnAnomalies.length > 0) {\n        actions.push(\"Contrôler les anomalies de niveau avertissement pour éviter une dérive future.\");\n      }\n\n      actions.push(\"Comparer résultat net, dépenses et recettes mois par mois pour détecter les déséquilibres.\");\n      actions.push(\"Vérifier les postes de dépenses dominants avant la clôture de période.\");\n\n      return actions;\n    }\n\n    const actions: string[] = [];\n\n    if (overdueCount > 0) {\n      actions.push(\"Relancer en priorité les factures en retard (mail + SMS si possible).\");\n      actions.push(\"Proposer un paiement en ligne (lien de règlement) pour réduire le délai de paiement.\");\n    }\n\n    if (unpaidCount > 5) {\n      actions.push(\"Mettre en place une relance automatique J+1 / J+7 / J+15 sur les factures sent/overdue.\");\n    }\n\n    actions.push(\"Déclencher la sync externe uniquement quand la facture est finalisée (status: sent) et avec des lignes stables.\");\n    actions.push(\"Suivre le DSO (délai moyen de paiement) et fixer un objectif de réduction.\");\n\n    return actions;\n  }, [hasComptaReport, resultatNet, criticalAnomalies.length, warnAnomalies.length, overdueCount, unpaidCount]);\n\n  return (\n    <div className=\"max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700\">\n      <div className=\"flex items-start justify-between gap-4\">\n        <div>\n          <Link\n            to=\"/dashboard\"\n            className=\"inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-[var(--theme-text)]\"\n          >\n            <ArrowLeft size={16} /> Retour\n          </Link>\n          <h2 className=\"text-3xl font-extrabold text-[var(--theme-text)] tracking-tight mt-2\">\n            {hasComptaReport ? \"Résultat net\" : \"Factures impayées\"}\n          </h2>\n          <p className=\"text-slate-500 mt-1\">\n            {hasComptaReport\n              ? \"Pilotage du résultat net issu de l’analyse comptable.\"\n              : \"Pilotage trésorerie: impayés, retards et actions recommandées.\"}\n          </p>\n        </div>\n\n        <div className=\"hidden sm:flex items-center gap-2 bg-[var(--theme-card)] border border-slate-100 rounded-2xl px-4 py-3 shadow-sm\">\n          <AlertTriangle className=\"text-red-500\" size={18} />\n          <span className=\"text-sm font-black text-[var(--theme-text)]\">\n            {loading\n              ? \"…\"\n              : hasComptaReport\n              ? formatEur(resultatNet)\n              : formatEurFromCents(unpaidTotalCents)}\n          </span>\n          <span className=\"text-xs font-bold text-slate-400\">\n            {hasComptaReport ? \"résultat net\" : \"à encaisser\"}\n          </span>\n        </div>\n      </div>\n\n      <div className=\"grid grid-cols-1 lg:grid-cols-4 gap-6\">\n        <Kpi\n          label={hasComptaReport ? \"Résultat net\" : \"Impayés\"}\n          value={\n            loading\n              ? \"…\"\n              : hasComptaReport\n              ? formatEur(resultatNet)\n              : String(unpaidCount)\n          }\n          hint={\n            hasComptaReport\n              ? \"Issu de l’analyse compta.\"\n              : \"factures sent/overdue\"\n          }\n        />\n        <Kpi\n          label={hasComptaReport ? \"Anomalies critiques\" : \"Montant impayé\"}\n          value={\n            loading\n              ? \"…\"\n              : hasComptaReport\n              ? String(criticalAnomalies.length)\n              : formatEurFromCents(unpaidTotalCents)\n          }\n          hint={\n            hasComptaReport\n              ? \"Points les plus urgents.\"\n              : \"total à encaisser\"\n          }\n        />\n        <Kpi\n          label={hasComptaReport ? \"Anomalies avertissement\" : \"En retard\"}\n          value={\n            loading\n              ? \"…\"\n              : hasComptaReport\n              ? String(warnAnomalies.length)\n              : String(overdueCount)\n          }\n          hint={\n            hasComptaReport\n              ? \"Vigilance recommandée.\"\n              : \"échéance dépassée\"\n          }\n        />\n        <Kpi\n          label={hasComptaReport ? \"Anomalies totales\" : \"Montant en retard\"}\n          value={\n            loading\n              ? \"…\"\n              : hasComptaReport\n              ? String(anomalies.length)\n              : formatEurFromCents(overdueTotalCents)\n          }\n          hint={\n            hasComptaReport\n              ? \"Détectées par l’IA.\"\n              : \"priorité relance\"\n          }\n        />\n      </div>\n\n      <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-8\">\n        <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n          <div className=\"p-6 border-b border-slate-50\">\n            <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">\n              {hasComptaReport ? \"Anomalies prioritaires\" : \"À relancer en priorité\"}\n            </h3>\n            <p className=\"text-[11px] text-slate-500 font-medium mt-1\">\n              {hasComptaReport\n                ? \"Issues de l’analyse IA.\"\n                : \"Top impayés (retard, puis montant).\"}\n            </p>\n          </div>\n\n          <div className=\"divide-y divide-slate-50\">\n            {hasComptaReport ? (\n              anomalies.length > 0 ? (\n                anomalies.slice(0, 10).map((it, idx) => (\n                  <div key={`${it.message}-${idx}`} className=\"p-4 flex items-center justify-between\">\n                    <div>\n                      <p className=\"text-sm font-bold text-[var(--theme-text)]\">{it.message}</p>\n                      <p className=\"text-xs text-slate-500 font-medium\">\n                        {it.sheet ? `Feuille: ${it.sheet}` : \"Analyse générale\"}\n                      </p>\n                    </div>\n                    <span\n                      className={`text-[10px] font-black px-2 py-1 rounded-lg uppercase tracking-widest ${\n                        it.severity === \"critical\"\n                          ? \"bg-red-100 text-red-700\"\n                          : it.severity === \"warn\"\n                          ? \"bg-amber-100 text-amber-700\"\n                          : \"bg-blue-100 text-blue-700\"\n                      }`}\n                    >\n                      {it.severity}\n                    </span>\n                  </div>\n                ))\n              ) : (\n                <div className=\"p-6 text-sm text-slate-500\">Aucune anomalie détectée.</div>\n              )\n            ) : preview.length > 0 ? (\n              preview.map((it) => (\n                <div key={it.id} className=\"p-4 flex items-center justify-between\">\n                  <div>\n                    <p className=\"text-sm font-bold text-[var(--theme-text)]\">{it.client}</p>\n                    <p className=\"text-xs text-slate-500 font-medium\">\n                      Échéance: {formatDateFr(it.dueDate)}\n                      {it.daysLate > 0 ? ` • ${it.daysLate}j de retard` : \"\"}\n                    </p>\n                  </div>\n                  <span className=\"text-sm font-black text-[var(--theme-text)]\">\n                    {formatEurFromCents(it.totalAmountCents)}\n                  </span>\n                </div>\n              ))\n            ) : (\n              <div className=\"p-6 text-sm text-slate-500\">Aucune relance prioritaire.</div>\n            )}\n          </div>\n        </div>\n\n        <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n          <div className=\"p-6 border-b border-slate-50\">\n            <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">Analyse & plan d’action</h3>\n            <p className=\"text-[11px] text-slate-500 font-medium mt-1\">\n              Suggestions pour améliorer la situation.\n            </p>\n          </div>\n          <div className=\"p-6\">\n            <ul className=\"space-y-2\">\n              {recommendations.map((a) => (\n                <li key={a} className=\"text-sm text-slate-600 flex gap-3\">\n                  <span className=\"mt-1.5 w-1.5 h-1.5 rounded-full bg-slate-300\" />\n                  <span>{a}</span>\n                </li>\n              ))}\n            </ul>\n          </div>\n        </div>\n      </div>\n\n      <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n        <div className=\"p-6 border-b border-slate-50 flex items-center justify-between\">\n          <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">\n            {hasComptaReport ? \"Détail des anomalies\" : \"Toutes les factures impayées\"}\n          </h3>\n\n          <div className=\"relative flex items-center gap-3\">\n            <span className=\"text-[10px] font-black uppercase tracking-widest text-slate-400\">\n              {loading\n                ? \"…\"\n                : hasComptaReport\n                ? `${anomalies.length} éléments`\n                : `${unpaid.length} éléments`}\n            </span>\n\n            <button\n              type=\"button\"\n              onClick={() => setMenuOpen((prev) => !prev)}\n              className=\"inline-flex items-center justify-center rounded-lg border border-[var(--theme-border)] p-2 text-slate-500 hover:bg-[var(--theme-bg)] hover:text-[var(--theme-text)]\"\n              aria-label=\"Ouvrir le menu\"\n            >\n              <MoreHorizontal size={16} />\n            </button>\n\n            {menuOpen ? (\n              <div className=\"absolute right-0 top-12 z-20 w-48 rounded-2xl border border-[var(--theme-border)] bg-[var(--theme-card)] p-2 shadow-xl\">\n                <Link\n                  to={hasComptaReport ? \"/compta\" : \"/invoices\"}\n                  onClick={() => setMenuOpen(false)}\n                  className=\"block rounded-xl px-3 py-2 text-sm font-medium text-slate-700 hover:bg-[var(--theme-bg)]\"\n                >\n                  {hasComptaReport ? \"Ouvrir Compta IA\" : \"Créer une facture\"}\n                </Link>\n              </div>\n            ) : null}\n          </div>\n        </div>\n\n        <div className=\"overflow-x-auto\">\n          <table className=\"min-w-full text-left\">\n            <thead className=\"bg-[var(--theme-bg)]/60\">\n              <tr className=\"text-xs font-black uppercase tracking-widest text-slate-400\">\n                <th className=\"px-4 py-3\">{hasComptaReport ? \"Élément\" : \"Client\"}</th>\n                <th className=\"px-4 py-3\">{hasComptaReport ? \"Source\" : \"Échéance\"}</th>\n                <th className=\"px-4 py-3\">{hasComptaReport ? \"Niveau\" : \"Statut\"}</th>\n                <th className=\"px-4 py-3 text-right\">\n                  {hasComptaReport ? \"Ligne\" : \"Montant\"}\n                </th>\n              </tr>\n            </thead>\n            <tbody className=\"divide-y divide-slate-50\">\n              {hasComptaReport ? (\n                anomalies.length > 0 ? (\n                  anomalies.map((it, idx) => (\n                    <tr key={`${it.message}-${idx}`} className=\"text-sm\">\n                      <td className=\"px-4 py-3 font-bold text-[var(--theme-text)]\">{it.message}</td>\n                      <td className=\"px-4 py-3 text-slate-600\">{it.sheet ?? \"—\"}</td>\n                      <td className=\"px-4 py-3\">\n                        <span\n                          className={`text-[10px] font-black px-2 py-1 rounded-lg uppercase tracking-widest ${\n                            it.severity === \"critical\"\n                              ? \"bg-red-100 text-red-700\"\n                              : it.severity === \"warn\"\n                              ? \"bg-amber-100 text-amber-700\"\n                              : \"bg-blue-100 text-blue-700\"\n                          }`}\n                        >\n                          {it.severity}\n                        </span>\n                      </td>\n                      <td className=\"px-4 py-3 text-right font-black text-[var(--theme-text)]\">\n                        {typeof it.rowIndex === \"number\" ? String(it.rowIndex) : \"—\"}\n                      </td>\n                    </tr>\n                  ))\n                ) : (\n                  <tr>\n                    <td className=\"px-4 py-6 text-sm text-slate-500\" colSpan={4}>\n                      Aucune anomalie détectée.\n                    </td>\n                  </tr>\n                )\n              ) : unpaid.length > 0 ? (\n                unpaid.map((it) => {\n                  const status = String(it.status).toLowerCase();\n                  const overdueFlag = new Date(it.due_date).getTime() < Date.now();\n\n                  return (\n                    <tr key={it.id} className=\"text-sm\">\n                      <td className=\"px-4 py-3 font-bold text-[var(--theme-text)]\">{it.client_name}</td>\n                      <td className=\"px-4 py-3 text-slate-600\">\n                        {formatDateFr(it.due_date)}\n                        {overdueFlag ? \" • en retard\" : \"\"}\n                      </td>\n                      <td className=\"px-4 py-3\">\n                        <span\n                          className={`text-[10px] font-black px-2 py-1 rounded-lg uppercase tracking-widest ${\n                            status === \"overdue\"\n                              ? \"bg-red-100 text-red-700\"\n                              : \"bg-amber-100 text-amber-700\"\n                          }`}\n                        >\n                          {status}\n                        </span>\n                      </td>\n                      <td className=\"px-4 py-3 text-right font-black text-[var(--theme-text)]\">\n                        {formatEurFromCents(invoiceAmountCents(it))}\n                      </td>\n                    </tr>\n                  );\n                })\n              ) : (\n                <tr>\n                  <td className=\"px-4 py-6 text-sm text-slate-500\" colSpan={4}>\n                    Aucune facture impayée.\n                  </td>\n                </tr>\n              )}\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction Kpi({ label, value, hint }: any) {\n  return (\n    <div className=\"bg-[var(--theme-card)] p-6 rounded-3xl border border-slate-100 shadow-sm\">\n      <p className=\"text-slate-500 text-sm font-medium\">{label}</p>\n      <div className=\"text-2xl font-black text-[var(--theme-text)] mt-1\">{value}</div>\n      <p className=\"text-[11px] text-slate-400 font-medium mt-2\">{hint}</p>\n    </div>\n  );\n}\n",
  "apps/frontend/src/pages/DashboardQuotes.tsx": "// apps/frontend/src/pages/DashboardQuotes.tsx\nimport React, { useEffect, useMemo, useRef, useState } from \"react\";\nimport { ArrowLeft, Clock } from \"lucide-react\";\nimport { Link } from \"react-router-dom\";\nimport { fetchWithAuth } from \"../auth/fetchWithAuth\";\nimport { useComptaReportStore } from \"../store/comptaReport.store\";\n\ntype DashboardResponse = {\n  kpis?: {\n    quotes?: { pendingCount: number };\n    revenue?: { paidMonthCents: number };\n  };\n};\n\nfunction formatEur(value: number): string {\n  return new Intl.NumberFormat(\"fr-FR\", {\n    style: \"currency\",\n    currency: \"EUR\",\n    maximumFractionDigits: 2,\n  }).format(Number.isFinite(value) ? value : 0);\n}\n\nexport default function DashboardQuotes() {\n  const report = useComptaReportStore((s) => s.report);\n\n  const [loading, setLoading] = useState(false);\n  const [pendingCount, setPendingCount] = useState<number>(0);\n  const fetchOnceRef = useRef(false);\n\n  useEffect(() => {\n    if (fetchOnceRef.current) return;\n    fetchOnceRef.current = true;\n\n    let cancelled = false;\n    setLoading(true);\n\n    (async () => {\n      try {\n        const dash = await fetchWithAuth<DashboardResponse>(\"/dashboard\", {\n          method: \"GET\",\n        });\n        if (!cancelled) {\n          setPendingCount(dash?.kpis?.quotes?.pendingCount ?? 0);\n        }\n      } catch {\n        if (!cancelled) setPendingCount(0);\n      } finally {\n        if (!cancelled) setLoading(false);\n      }\n    })();\n\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n\n  const hasComptaReport = !!report;\n  const depensesHT = report?.totals?.depensesHT ?? 0;\n  const depensesTTC = report?.totals?.depensesTTC ?? 0;\n  const topDepenses = report?.breakdown?.topDepenses ?? [];\n  const anomalies = report?.anomalies ?? [];\n\n  const analysis = useMemo(() => {\n    if (hasComptaReport) {\n      return {\n        summary:\n          anomalies.length > 0\n            ? `${anomalies.length} anomalie(s) détectée(s). Dépenses analysées : ${formatEur(\n                depensesTTC\n              )} TTC pour ${formatEur(depensesHT)} HT.`\n            : `Dépenses analysées : ${formatEur(depensesTTC)} TTC pour ${formatEur(\n                depensesHT\n              )} HT.`,\n        actions: [\n          \"Contrôler les plus gros postes de dépenses pour identifier les dérives.\",\n          \"Comparer les charges récurrentes avec les mois précédents.\",\n          \"Prioriser les anomalies critiques détectées par l’analyse IA.\",\n          \"Rattacher les dépenses aux chantiers pour un pilotage BTP plus fin.\",\n        ],\n      };\n    }\n\n    const actions = [\n      \"Définir le statut devis (draft/sent/accepted/refused) comme source de vérité côté backend.\",\n      \"Relier devis → facture (invoice_id) pour mesurer le taux de conversion.\",\n      \"Relance devis envoyés à J+2 / J+7 (gain direct sur le CA).\",\n      \"Ajouter un champ chantier/projet sur le devis pour un pilotage BTP cohérent.\",\n    ];\n\n    return {\n      summary:\n        pendingCount > 0\n          ? `${pendingCount} devis en attente (valeur exacte non disponible tant que le backend devis n’est pas branché).`\n          : \"Aucun devis en attente (ou backend devis non branché).\",\n      actions,\n    };\n  }, [hasComptaReport, anomalies.length, depensesTTC, depensesHT, pendingCount]);\n\n  return (\n    <div className=\"max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700\">\n      <div className=\"flex items-start justify-between gap-4\">\n        <div>\n          <Link\n            to=\"/dashboard\"\n            className=\"inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-[var(--theme-text)]\"\n          >\n            <ArrowLeft size={16} /> Retour\n          </Link>\n          <h2 className=\"text-3xl font-extrabold text-[var(--theme-text)] tracking-tight mt-2\">\n            {hasComptaReport ? \"Dépenses\" : \"Devis en attente\"}\n          </h2>\n          <p className=\"text-slate-500 mt-1\">\n            {hasComptaReport\n              ? \"Analyse structurée des dépenses issues de la compta IA.\"\n              : \"Analyse structurée + prochaines améliorations (devis backend à finaliser).\"}\n          </p>\n        </div>\n\n        <div className=\"hidden sm:flex items-center gap-2 bg-[var(--theme-card)] border border-slate-100 rounded-2xl px-4 py-3 shadow-sm\">\n          <Clock className=\"text-amber-500\" size={18} />\n          <span className=\"text-sm font-black text-[var(--theme-text)]\">\n            {loading\n              ? \"…\"\n              : hasComptaReport\n              ? formatEur(depensesTTC)\n              : String(pendingCount)}\n          </span>\n          <span className=\"text-xs font-bold text-slate-400\">\n            {hasComptaReport ? \"dépenses\" : \"en attente\"}\n          </span>\n        </div>\n      </div>\n\n      <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-8\">\n        <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n          <div className=\"p-6 border-b border-slate-50\">\n            <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">Analyse</h3>\n            <p className=\"text-[11px] text-slate-500 font-medium mt-1\">\n              Ce que l’écran peut faire dès maintenant.\n            </p>\n          </div>\n          <div className=\"p-6 space-y-4\">\n            <p className=\"text-sm font-medium text-slate-700\">{analysis.summary}</p>\n            <ul className=\"space-y-2\">\n              {analysis.actions.map((a) => (\n                <li key={a} className=\"text-sm text-slate-600 flex gap-3\">\n                  <span className=\"mt-1.5 w-1.5 h-1.5 rounded-full bg-slate-300\" />\n                  <span>{a}</span>\n                </li>\n              ))}\n            </ul>\n          </div>\n        </div>\n\n        <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n          <div className=\"p-6 border-b border-slate-50\">\n            <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">\n              {hasComptaReport ? \"Top dépenses\" : \"Actions rapides\"}\n            </h3>\n            <p className=\"text-[11px] text-slate-500 font-medium mt-1\">\n              {hasComptaReport\n                ? \"Postes détectés par l’analyse comptable.\"\n                : \"Aller vers la source de vérité.\"}\n            </p>\n          </div>\n\n          <div className=\"p-6 space-y-3\">\n            {hasComptaReport ? (\n              topDepenses.length > 0 ? (\n                topDepenses.slice(0, 10).map((item) => (\n                  <div\n                    key={item.label}\n                    className=\"flex items-center justify-between rounded-2xl border border-slate-100 px-4 py-3\"\n                  >\n                    <div>\n                      <p className=\"text-sm font-bold text-[var(--theme-text)]\">{item.label}</p>\n                      <p className=\"text-xs text-slate-500 font-medium\">\n                        {item.count} occurrence(s)\n                      </p>\n                    </div>\n                    <span className=\"text-sm font-black text-[var(--theme-text)]\">\n                      {formatEur(item.amountHT)}\n                    </span>\n                  </div>\n                ))\n              ) : (\n                <p className=\"text-xs text-slate-400 font-medium\">\n                  Aucune dépense détaillée détectée.\n                </p>\n              )\n            ) : (\n              <>\n                <Link\n                  to=\"/devis\"\n                  className=\"block bg-slate-900 text-white px-4 py-3 rounded-2xl font-bold text-sm hover:bg-blue-600 transition-colors\"\n                >\n                  Ouvrir le module Devis\n                </Link>\n                <Link\n                  to=\"/dashboard\"\n                  className=\"block bg-[var(--theme-card)] border border-[var(--theme-border)] text-[var(--theme-text)] px-4 py-3 rounded-2xl font-bold text-sm hover:border-blue-200 hover:bg-blue-50/30 transition-colors\"\n                >\n                  Revenir au dashboard\n                </Link>\n                <p className=\"text-xs text-slate-400 font-medium\">\n                  Note: pour afficher une vraie liste “devis en attente”, il faudra brancher le backend devis (table + statuts) comme on l’a fait pour les factures.\n                </p>\n              </>\n            )}\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "apps/frontend/src/components/invoices/InvoiceEditor.tsx": "// apps/frontend/src/components/invoices/InvoiceEditor.tsx\nimport React, { useEffect, useMemo, useState } from \"react\";\nimport type { Invoice } from \"../../services/invoices.api\";\nimport { listProjects, type Project } from \"../../api/projects.api\";\n\ntype Props = {\n  loading: boolean;\n  invoice: Invoice | null;\n  onSave: (patch: {\n    client_name: string;\n    client_email: string | null;\n    due_date: string;\n    project_id: string | null;\n  }) => Promise<void> | void;\n};\n\nexport default function InvoiceEditor({ loading, invoice, onSave }: Props) {\n  const [clientName, setClientName] = useState(\"\");\n  const [clientEmail, setClientEmail] = useState<string>(\"\");\n  const [dueDate, setDueDate] = useState<string>(\"\");\n  const [projectId, setProjectId] = useState<string>(\"\");\n\n  const [projects, setProjects] = useState<Project[]>([]);\n  const [projectsLoading, setProjectsLoading] = useState(false);\n\n  useEffect(() => {\n    setClientName(invoice?.client_name ?? \"\");\n    setClientEmail(invoice?.client_email ?? \"\");\n    setDueDate((invoice?.due_date ?? \"\").slice(0, 10));\n    setProjectId(invoice?.project_id ?? \"\");\n  }, [invoice?.id, invoice?.client_name, invoice?.client_email, invoice?.due_date, invoice?.project_id]);\n\n  useEffect(() => {\n    let isMounted = true;\n\n    const loadProjects = async () => {\n      setProjectsLoading(true);\n      try {\n        const data = await listProjects();\n        if (!isMounted) return;\n        setProjects(Array.isArray(data) ? data : []);\n      } catch {\n        if (!isMounted) return;\n        setProjects([]);\n      } finally {\n        if (isMounted) {\n          setProjectsLoading(false);\n        }\n      }\n    };\n\n    void loadProjects();\n\n    return () => {\n      isMounted = false;\n    };\n  }, []);\n\n  const canSave = useMemo(() => {\n    if (!invoice) return false;\n    if (!clientName.trim()) return false;\n    if (!dueDate.trim()) return false;\n    return true;\n  }, [invoice, clientName, dueDate]);\n\n  const submit = async () => {\n    if (!canSave) return;\n\n    await onSave({\n      client_name: clientName.trim(),\n      client_email: clientEmail.trim() ? clientEmail.trim() : null,\n      due_date: new Date(dueDate).toISOString(),\n      project_id: projectId.trim() ? projectId : null,\n    });\n  };\n\n  return (\n    <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n      <div className=\"p-6 border-b border-slate-50\">\n        <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">Informations client</h3>\n        <p className=\"text-[11px] text-slate-500 font-medium mt-1\">\n          Renseigne le client, l’échéance et rattache la facture à un chantier si\n          besoin. Le reste est calculé via les lignes.\n        </p>\n      </div>\n\n      <div className=\"p-6 grid grid-cols-1 md:grid-cols-2 gap-4\">\n        <Field label=\"Nom client\">\n          <input\n            value={clientName}\n            onChange={(e) => setClientName(e.target.value)}\n            className=\"w-full px-4 py-3 rounded-2xl border border-[var(--theme-border)] outline-none focus:border-blue-300 bg-[var(--theme-card)] text-sm font-semibold text-[var(--theme-text)]\"\n            placeholder=\"Nom / Société\"\n          />\n        </Field>\n\n        <Field label=\"Email (optionnel)\">\n          <input\n            value={clientEmail}\n            onChange={(e) => setClientEmail(e.target.value)}\n            className=\"w-full px-4 py-3 rounded-2xl border border-[var(--theme-border)] outline-none focus:border-blue-300 bg-[var(--theme-card)] text-sm font-semibold text-[var(--theme-text)]\"\n            placeholder=\"client@mail.com\"\n          />\n        </Field>\n\n        <Field label=\"Date d’échéance\">\n          <input\n            type=\"date\"\n            value={dueDate}\n            onChange={(e) => setDueDate(e.target.value)}\n            className=\"w-full px-4 py-3 rounded-2xl border border-[var(--theme-border)] outline-none focus:border-blue-300 bg-[var(--theme-card)] text-sm font-semibold text-[var(--theme-text)]\"\n          />\n        </Field>\n\n        <Field label=\"Chantier (optionnel)\">\n          <select\n            value={projectId}\n            onChange={(e) => setProjectId(e.target.value)}\n            className=\"w-full px-4 py-3 rounded-2xl border border-[var(--theme-border)] outline-none focus:border-blue-300 bg-[var(--theme-card)] text-sm font-semibold text-[var(--theme-text)]\"\n          >\n            <option value=\"\">\n              {projectsLoading ? \"Chargement des chantiers…\" : \"Aucun chantier\"}\n            </option>\n\n            {projects.map((project) => (\n              <option key={project.id} value={project.id}>\n                {project.name}\n              </option>\n            ))}\n          </select>\n        </Field>\n\n        <div className=\"md:col-span-2 flex items-end justify-end\">\n          <button\n            onClick={submit}\n            disabled={!canSave || loading}\n            className=\"inline-flex items-center justify-center bg-slate-900 text-white px-5 py-3 rounded-2xl font-bold text-sm hover:bg-blue-600 transition-colors disabled:opacity-60 w-full md:w-auto\"\n          >\n            Enregistrer\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction Field({\n  label,\n  children,\n}: {\n  label: string;\n  children: React.ReactNode;\n}) {\n  return (\n    <div className=\"space-y-2\">\n      <div className=\"text-xs font-black uppercase tracking-widest text-slate-400\">\n        {label}\n      </div>\n      {children}\n    </div>\n  );\n}\n",
  "apps/frontend/src/components/invoices/InvoiceLinesEditor.tsx": "// apps/frontend/src/components/invoices/InvoiceLinesEditor.tsx\nimport React, { useMemo, useState } from \"react\";\nimport { Plus, Trash2, Pencil, RefreshCw } from \"lucide-react\";\nimport {\n  createInvoiceLine,\n  deleteInvoiceLine,\n  patchInvoiceLine,\n  type InvoiceLine,\n} from \"../../services/invoices.api\"; // ✅ MODIF: chemin corrigé\n\ntype Props = {\n  loading: boolean;\n  invoiceId: string;\n  lines: InvoiceLine[];\n  onChangeLines: (lines: InvoiceLine[]) => void;\n  onReload: () => Promise<void> | void;\n};\n\nfunction formatEurFromCents(cents: number): string {\n  const euros = (Number.isFinite(cents) ? cents : 0) / 100;\n  return new Intl.NumberFormat(\"fr-FR\", {\n    style: \"currency\",\n    currency: \"EUR\",\n    maximumFractionDigits: 2,\n  }).format(euros);\n}\n\nexport default function InvoiceLinesEditor({\n  loading,\n  invoiceId,\n  lines,\n  onChangeLines,\n  onReload,\n}: Props) {\n  const [draftDesc, setDraftDesc] = useState(\"\");\n  const [draftQty, setDraftQty] = useState<number>(1);\n  const [draftUnitEur, setDraftUnitEur] = useState<string>(\"0\");\n  const [draftTax, setDraftTax] = useState<number>(20);\n\n  const [editingId, setEditingId] = useState<string | null>(null);\n\n  const totals = useMemo(() => {\n    const subtotal = lines.reduce((a, l) => a + (l.line_total_cents ?? 0), 0);\n    const tax = lines.reduce((a, l) => {\n      const rate = Number.isFinite(l.tax_rate) ? l.tax_rate : 0;\n      return a + Math.round((l.line_total_cents ?? 0) * (rate / 100));\n    }, 0);\n    return { subtotal, tax, total: subtotal + tax };\n  }, [lines]);\n\n  const unitCents = useMemo(() => {\n    const n = Number(String(draftUnitEur).replace(\",\", \".\"));\n    if (!Number.isFinite(n)) return 0;\n    return Math.round(n * 100);\n  }, [draftUnitEur]);\n\n  const add = async () => {\n    const desc = draftDesc.trim();\n    if (!desc) return;\n\n    try {\n      const created = await createInvoiceLine({\n        invoice_id: invoiceId,\n        description: desc,\n        quantity: draftQty,\n        unit_price_cents: unitCents,\n        tax_rate: draftTax,\n      });\n\n      onChangeLines([...lines, created]);\n      setDraftDesc(\"\");\n      setDraftQty(1);\n      setDraftUnitEur(\"0\");\n      setDraftTax(20);\n    } catch {\n      // best-effort\n    }\n  };\n\n  const remove = async (id: string) => {\n    try {\n      await deleteInvoiceLine(id);\n      onChangeLines(lines.filter((l) => l.id !== id));\n    } catch {\n      // best-effort\n    }\n  };\n\n  const startEdit = (id: string) => setEditingId(id);\n  const stopEdit = () => setEditingId(null);\n\n  const saveEdit = async (line: InvoiceLine, patch: Partial<InvoiceLine>) => {\n    try {\n      const updated = await patchInvoiceLine(line.id, {\n        description: patch.description ?? line.description,\n        quantity: patch.quantity ?? line.quantity,\n        unit_price_cents: patch.unit_price_cents ?? line.unit_price_cents,\n        tax_rate: patch.tax_rate ?? line.tax_rate,\n      });\n\n      onChangeLines(lines.map((l) => (l.id === line.id ? updated : l)));\n      stopEdit();\n    } catch {\n      // best-effort\n    }\n  };\n\n  return (\n    <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden\">\n      <div className=\"p-6 border-b border-slate-50 flex items-center justify-between gap-3\">\n        <div>\n          <h3 className=\"text-lg font-bold text-[var(--theme-text)]\">Lignes de facture</h3>\n          <p className=\"text-[11px] text-slate-500 font-medium mt-1\">\n            Ajoute au moins 1 ligne avant de finaliser.\n          </p>\n        </div>\n\n        <button\n          onClick={() => onReload()}\n          disabled={loading}\n          className=\"inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-[var(--theme-text)] disabled:opacity-60\"\n        >\n          <RefreshCw size={16} /> Recharger\n        </button>\n      </div>\n\n      <div className=\"p-6 space-y-4\">\n        {/* Ajout ligne */}\n        <div className=\"grid grid-cols-1 md:grid-cols-6 gap-3\">\n          <div className=\"md:col-span-2\">\n            <Label>Description</Label>\n            <input\n              value={draftDesc}\n              onChange={(e) => setDraftDesc(e.target.value)}\n              placeholder=\"Ex: Main d’œuvre\"\n              className=\"w-full px-4 py-3 rounded-2xl border border-[var(--theme-border)] outline-none focus:border-blue-300 bg-[var(--theme-card)] text-sm font-semibold text-[var(--theme-text)]\"\n            />\n          </div>\n\n          <div>\n            <Label>Qté</Label>\n            <input\n              type=\"number\"\n              min={0}\n              step={1}\n              value={draftQty}\n              onChange={(e) => setDraftQty(Number(e.target.value))}\n              className=\"w-full px-4 py-3 rounded-2xl border border-[var(--theme-border)] outline-none focus:border-blue-300 bg-[var(--theme-card)] text-sm font-semibold text-[var(--theme-text)]\"\n            />\n          </div>\n\n          <div>\n            <Label>PU (€)</Label>\n            <input\n              value={draftUnitEur}\n              onChange={(e) => setDraftUnitEur(e.target.value)}\n              className=\"w-full px-4 py-3 rounded-2xl border border-[var(--theme-border)] outline-none focus:border-blue-300 bg-[var(--theme-card)] text-sm font-semibold text-[var(--theme-text)]\"\n            />\n          </div>\n\n          <div>\n            <Label>TVA (%)</Label>\n            <input\n              type=\"number\"\n              min={0}\n              step={0.1}\n              value={draftTax}\n              onChange={(e) => setDraftTax(Number(e.target.value))}\n              className=\"w-full px-4 py-3 rounded-2xl border border-[var(--theme-border)] outline-none focus:border-blue-300 bg-[var(--theme-card)] text-sm font-semibold text-[var(--theme-text)]\"\n            />\n          </div>\n\n          <div className=\"flex items-end\">\n            <button\n              onClick={add}\n              disabled={loading || !draftDesc.trim()}\n              className=\"w-full inline-flex items-center justify-center gap-2 bg-slate-900 text-white px-4 py-3 rounded-2xl font-bold text-sm hover:bg-blue-600 transition-colors disabled:opacity-60\"\n            >\n              <Plus size={16} /> Ajouter\n            </button>\n          </div>\n        </div>\n\n        {/* Table */}\n        <div className=\"overflow-x-auto\">\n          <table className=\"min-w-full text-left\">\n            <thead className=\"bg-[var(--theme-bg)]/60\">\n              <tr className=\"text-xs font-black uppercase tracking-widest text-slate-400\">\n                <th className=\"px-3 py-3\">Description</th>\n                <th className=\"px-3 py-3\">Qté</th>\n                <th className=\"px-3 py-3\">PU</th>\n                <th className=\"px-3 py-3\">TVA</th>\n                <th className=\"px-3 py-3 text-right\">Total HT</th>\n                <th className=\"px-3 py-3 text-right\">Actions</th>\n              </tr>\n            </thead>\n\n            <tbody className=\"divide-y divide-slate-50\">\n              {lines.length > 0 ? (\n                lines.map((l) => (\n                  <LineRow\n                    key={l.id}\n                    line={l}\n                    isEditing={editingId === l.id}\n                    onStartEdit={() => startEdit(l.id)}\n                    onCancel={stopEdit}\n                    onSave={(patch: Partial<InvoiceLine>) => saveEdit(l, patch)} // ✅ MODIF: typage patch\n                    onDelete={() => remove(l.id)}\n                  />\n                ))\n              ) : (\n                <tr>\n                  <td className=\"px-3 py-6 text-sm text-slate-500\" colSpan={6}>\n                    Aucune ligne.\n                  </td>\n                </tr>\n              )}\n            </tbody>\n\n            {lines.length > 0 ? (\n              <tfoot className=\"bg-[var(--theme-bg)]/40\">\n                <tr>\n                  <td\n                    className=\"px-3 py-3 text-xs font-black uppercase tracking-widest text-slate-400\"\n                    colSpan={4}\n                  >\n                    Totaux (estimations)\n                  </td>\n                  <td className=\"px-3 py-3 text-right font-black text-[var(--theme-text)]\">\n                    {formatEurFromCents(totals.subtotal)}\n                  </td>\n                  <td className=\"px-3 py-3 text-right text-sm font-black text-[var(--theme-text)]\">\n                    TTC: {formatEurFromCents(totals.total)}\n                  </td>\n                </tr>\n              </tfoot>\n            ) : null}\n          </table>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction Label({ children }: { children: React.ReactNode }) {\n  return (\n    <div className=\"text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2\">\n      {children}\n    </div>\n  );\n}\n\n// ✅ MODIF: typage des props (évite patch:any implicite)\ntype LineRowProps = {\n  line: InvoiceLine;\n  isEditing: boolean;\n  onStartEdit: () => void;\n  onCancel: () => void;\n  onSave: (patch: Partial<InvoiceLine>) => void;\n  onDelete: () => void;\n};\n\nfunction LineRow({\n  line,\n  isEditing,\n  onStartEdit,\n  onCancel,\n  onSave,\n  onDelete,\n}: LineRowProps) {\n  const [desc, setDesc] = useState(line.description);\n  const [qty, setQty] = useState<number>(line.quantity);\n  const [unit, setUnit] = useState<number>(line.unit_price_cents);\n  const [tax, setTax] = useState<number>(line.tax_rate);\n\n  React.useEffect(() => {\n    setDesc(line.description);\n    setQty(line.quantity);\n    setUnit(line.unit_price_cents);\n    setTax(line.tax_rate);\n  }, [line.id]);\n\n  const totalHT = Math.round(qty * unit);\n\n  return (\n    <tr className=\"text-sm\">\n      <td className=\"px-3 py-3 font-semibold text-[var(--theme-text)]\">\n        {isEditing ? (\n          <input\n            value={desc}\n            onChange={(e) => setDesc(e.target.value)}\n            className=\"w-full px-3 py-2 rounded-xl border border-[var(--theme-border)] outline-none focus:border-blue-300\"\n          />\n        ) : (\n          line.description\n        )}\n      </td>\n\n      <td className=\"px-3 py-3 text-slate-700\">\n        {isEditing ? (\n          <input\n            type=\"number\"\n            min={0}\n            step={1}\n            value={qty}\n            onChange={(e) => setQty(Number(e.target.value))}\n            className=\"w-24 px-3 py-2 rounded-xl border border-[var(--theme-border)] outline-none focus:border-blue-300\"\n          />\n        ) : (\n          line.quantity\n        )}\n      </td>\n\n      <td className=\"px-3 py-3 text-slate-700\">\n        {isEditing ? (\n          <input\n            type=\"number\"\n            min={0}\n            step={1}\n            value={unit}\n            onChange={(e) => setUnit(Number(e.target.value))}\n            className=\"w-28 px-3 py-2 rounded-xl border border-[var(--theme-border)] outline-none focus:border-blue-300\"\n          />\n        ) : (\n          `${formatEurFromCents(line.unit_price_cents)}`\n        )}\n      </td>\n\n      <td className=\"px-3 py-3 text-slate-700\">\n        {isEditing ? (\n          <input\n            type=\"number\"\n            min={0}\n            step={0.1}\n            value={tax}\n            onChange={(e) => setTax(Number(e.target.value))}\n            className=\"w-24 px-3 py-2 rounded-xl border border-[var(--theme-border)] outline-none focus:border-blue-300\"\n          />\n        ) : (\n          `${line.tax_rate}%`\n        )}\n      </td>\n\n      <td className=\"px-3 py-3 text-right font-black text-[var(--theme-text)]\">\n        {formatEurFromCents(totalHT)}\n      </td>\n\n      <td className=\"px-3 py-3 text-right\">\n        {isEditing ? (\n          <div className=\"inline-flex items-center gap-2\">\n            <button\n              onClick={() =>\n                onSave({\n                  description: desc,\n                  quantity: qty,\n                  unit_price_cents: unit,\n                  tax_rate: tax,\n                })\n              }\n              className=\"px-3 py-2 rounded-xl bg-slate-900 text-white font-bold text-xs hover:bg-blue-600 transition-colors\"\n            >\n              OK\n            </button>\n            <button\n              onClick={onCancel}\n              className=\"px-3 py-2 rounded-xl bg-[var(--theme-card)] border border-[var(--theme-border)] text-slate-700 font-bold text-xs hover:bg-[var(--theme-bg)] transition-colors\"\n            >\n              Annuler\n            </button>\n          </div>\n        ) : (\n          <div className=\"inline-flex items-center gap-2\">\n            <button\n              onClick={onStartEdit}\n              className=\"p-2 rounded-xl bg-[var(--theme-card)] border border-[var(--theme-border)] text-slate-700 hover:bg-[var(--theme-bg)] transition-colors\"\n              title=\"Modifier\"\n            >\n              <Pencil size={14} />\n            </button>\n            <button\n              onClick={onDelete}\n              className=\"p-2 rounded-xl bg-[var(--theme-card)] border border-red-200 text-red-700 hover:bg-red-50 transition-colors\"\n              title=\"Supprimer\"\n            >\n              <Trash2 size={14} />\n            </button>\n          </div>\n        )}\n      </td>\n    </tr>\n  );\n}\n",
  "apps/frontend/src/components/devis/DevisAiActions.tsx": "// apps/frontend/src/components/devis/DevisAiActions.tsx\nimport React, { useEffect, useRef, useState } from \"react\";\nimport { Mic, FileUp, Loader2, StopCircle } from \"lucide-react\";\nimport { toast } from \"react-hot-toast\";\nimport { fetchWithAuth } from \"../../auth/fetchWithAuth\";\nimport { ApiRequestError } from \"../../utils/apiRequestError\";\n\ninterface DevisAiActionsProps {\n  onAnalysisComplete: (data: any) => void;\n}\n\nexport const DevisAiActions = ({ onAnalysisComplete }: DevisAiActionsProps) => {\n  const fileInputRef = useRef<HTMLInputElement>(null);\n  const [isProcessing, setIsProcessing] = useState(false);\n  const [isRecording, setIsRecording] = useState(false);\n\n  const mediaRecorderRef = useRef<MediaRecorder | null>(null);\n  const audioChunksRef = useRef<Blob[]>([]);\n\n  // ✅ Anti multi-poll + cleanup\n  const pollIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);\n  const isPollingRef = useRef(false);\n\n  useEffect(() => {\n    return () => {\n      if (pollIntervalRef.current) {\n        clearInterval(pollIntervalRef.current);\n        pollIntervalRef.current = null;\n      }\n      isPollingRef.current = false;\n    };\n  }, []);\n\n  const clearPoll = () => {\n    if (pollIntervalRef.current) {\n      clearInterval(pollIntervalRef.current);\n      pollIntervalRef.current = null;\n    }\n    isPollingRef.current = false;\n  };\n\n  // --- 1. FONCTION COMMUNE POUR APPELER L'API ---\n  const sendToAI = async (formData: FormData) => {\n    // ✅ Stoppe un poll en cours si l’utilisateur relance\n    clearPoll();\n\n    setIsProcessing(true);\n    const loadingToast = toast.loading(\"L'IA analyse votre demande...\");\n\n    try {\n      const { jobId } = await fetchWithAuth<{ jobId: string }>(\"/ai/run\", {\n        method: \"POST\",\n        body: formData,\n      });\n\n      pollJobStatus(jobId, loadingToast);\n    } catch (e) {\n      const err = e as ApiRequestError;\n\n      if (err.code === \"quota_exceeded\") {\n        toast.error(\"Quota atteint. Passez en PRO pour continuer.\", {\n          id: loadingToast,\n        });\n      } else {\n        toast.error(err.message || \"Erreur de connexion au serveur\", {\n          id: loadingToast,\n        });\n      }\n\n      setIsProcessing(false);\n      clearPoll();\n    }\n  };\n\n  // --- 2. LOGIQUE UPLOAD FICHIER ---\n  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {\n    const file = e.target.files?.[0];\n    if (!file) return;\n\n    const formData = new FormData();\n    formData.append(\"file\", file);\n    formData.append(\"type\", \"vision\");\n\n    sendToAI(formData);\n\n    // reset input\n    if (fileInputRef.current) fileInputRef.current.value = \"\";\n  };\n\n  // --- 3. LOGIQUE VOCALE ---\n  const toggleRecording = async () => {\n    if (isRecording) {\n      mediaRecorderRef.current?.stop();\n      setIsRecording(false);\n      return;\n    }\n\n    try {\n      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });\n      const mediaRecorder = new MediaRecorder(stream);\n      mediaRecorderRef.current = mediaRecorder;\n      audioChunksRef.current = [];\n\n      mediaRecorder.ondataavailable = (e) => audioChunksRef.current.push(e.data);\n\n      mediaRecorder.onstop = () => {\n        const audioBlob = new Blob(audioChunksRef.current, {\n          type: \"audio/webm\",\n        });\n        const formData = new FormData();\n        formData.append(\"file\", audioBlob, \"recording.webm\");\n        formData.append(\"type\", \"vocal\");\n\n        sendToAI(formData);\n\n        stream.getTracks().forEach((track) => track.stop());\n      };\n\n      mediaRecorder.start();\n      setIsRecording(true);\n    } catch {\n      toast.error(\"Micro introuvable ou refusé\");\n    }\n  };\n\n  // --- 4. POLLING (BULLMQ) ---\n  const pollJobStatus = (jobId: string, toastId: string) => {\n    // ✅ Empêche plusieurs polls simultanés\n    if (isPollingRef.current) return;\n    isPollingRef.current = true;\n\n    // ✅ Backoff 429 : 1s → 2s → 4s → 8s → 10s (max)\n    let delayMs = 1000;\n    const maxDelayMs = 10000;\n\n    const tick = async () => {\n      try {\n        const data = await fetchWithAuth<any>(`/ai/status/${jobId}`);\n\n        if (data.status === \"completed\") {\n          clearPoll();\n          setIsProcessing(false);\n\n          const result =\n            typeof data.result === \"string\" ? JSON.parse(data.result) : data.result;\n\n          onAnalysisComplete(result);\n          toast.success(\"Analyse terminée avec succès !\", { id: toastId });\n          return;\n        }\n\n        if (data.status === \"failed\") {\n          clearPoll();\n          setIsProcessing(false);\n          toast.error(\"L'IA n'a pas pu traiter la demande\", { id: toastId });\n          return;\n        }\n\n        // status pending/running → continuer\n      } catch (e) {\n        const err = e as ApiRequestError;\n\n        // ✅ 429 backoff + reprise du polling\n        if ((err as any).status === 429 || err.code === \"too_many_requests\") {\n          clearPoll();\n          delayMs = Math.min(maxDelayMs, delayMs * 2);\n          toast.error(\"Trop de requêtes, nouvelle tentative...\", { id: toastId });\n\n          isPollingRef.current = true;\n          pollIntervalRef.current = setInterval(tick, delayMs);\n          return;\n        }\n\n        // ✅ Clear interval dans tous les chemins d’erreur\n        clearPoll();\n        setIsProcessing(false);\n\n        if (err.code === \"quota_exceeded\") {\n          toast.error(\"Quota atteint. Passez en PRO pour continuer.\", {\n            id: toastId,\n          });\n        } else {\n          toast.error(err.message || \"Perte de connexion\", { id: toastId });\n        }\n      }\n    };\n\n    // Démarrage immédiat, puis interval\n    tick();\n    pollIntervalRef.current = setInterval(tick, delayMs);\n  };\n\n  return (\n    <div className=\"flex items-center gap-3 bg-[var(--theme-card)] p-2 rounded-xl border border-[var(--theme-border)]\">\n      <input\n        type=\"file\"\n        ref={fileInputRef}\n        className=\"hidden\"\n        onChange={handleFileUpload}\n        accept=\"image/*,application/pdf\"\n      />\n\n      <button\n        type=\"button\"\n        onClick={() => fileInputRef.current?.click()}\n        disabled={isProcessing || isRecording}\n        className=\"p-2 hover:bg-blue-50 text-blue-600 rounded-lg transition-colors disabled:opacity-50\"\n      >\n        {isProcessing ? (\n          <Loader2 className=\"w-6 h-6 animate-spin\" />\n        ) : (\n          <FileUp className=\"w-6 h-6\" />\n        )}\n      </button>\n\n      <div className=\"w-[1px] h-6 bg-slate-200\" />\n\n      <button\n        type=\"button\"\n        onClick={toggleRecording}\n        disabled={isProcessing}\n        className={`p-2 rounded-lg transition-colors ${\n          isRecording\n            ? \"bg-red-500 text-white animate-pulse\"\n            : \"hover:bg-red-50 text-red-500\"\n        }`}\n      >\n        {isRecording ? (\n          <StopCircle className=\"w-6 h-6\" />\n        ) : (\n          <Mic className=\"w-6 h-6\" />\n        )}\n      </button>\n    </div>\n  );\n};\n",
  "apps/frontend/src/components/devis/DevisForm.tsx": "// apps/frontend/src/components/devis/DevisForm.tsx\nimport React, { useState } from \"react\";\nimport { Save, Plus, Trash2, Calculator, Loader2 } from \"lucide-react\";\nimport { DevisAiActions } from \"./DevisAiActions\";\nimport { toast } from \"react-hot-toast\";\nimport { fetchWithAuth } from \"../../auth/fetchWithAuth\";\nimport { ApiRequestError } from \"../../utils/apiRequestError\";\n\n// Définition de l'interface pour un article de devis\ninterface DevisItem {\n  description: string;\n  quantity: number;\n  unitPrice: number;\n}\n\nexport const DevisForm = () => {\n  // --- ÉTATS DU FORMULAIRE ---\n  const [clientName, setClientName] = useState(\"\");\n  const [items, setItems] = useState<DevisItem[]>([\n    { description: \"\", quantity: 1, unitPrice: 0 },\n  ]);\n  const [isSubmitting, setIsSubmitting] = useState(false);\n\n  // --- RÉCEPTION DES DONNÉES DE L'IA ---\n  const handleAiAnalysis = (data: any) => {\n    if (data.client) setClientName(data.client);\n\n    if (data.items && Array.isArray(data.items)) {\n      const formattedItems: DevisItem[] = data.items.map((item: any) => ({\n        description: String(item.description || \"\"),\n        quantity: Number(item.quantity) || 1,\n        unitPrice: Number(item.unitPrice) || 0,\n      }));\n      setItems(formattedItems);\n      toast.success(\"Données extraites avec succès !\");\n    }\n  };\n\n  // --- GESTION DES ARTICLES ---\n  const addItem = () => {\n    setItems([...items, { description: \"\", quantity: 1, unitPrice: 0 }]);\n  };\n\n  const removeItem = (index: number) => {\n    if (items.length > 1) {\n      setItems(items.filter((_, i) => i !== index));\n    } else {\n      toast.error(\"Le devis doit contenir au moins une ligne.\");\n    }\n  };\n\n  /**\n   * Mise à jour d'un champ spécifique d'un article\n   * Correction de l'erreur TS(2322) par reconstruction explicite de l'objet\n   */\n  const updateItem = (index: number, field: keyof DevisItem, value: string) => {\n    const newItems = [...items];\n    const currentItem = newItems[index];\n\n    // On prépare la valeur (on convertit en nombre si c'est quantity ou unitPrice)\n    const processedValue =\n      field === \"quantity\" || field === \"unitPrice\"\n        ? parseFloat(value) || 0\n        : value;\n\n    // Reconstruction propre de l'objet pour satisfaire TypeScript\n    newItems[index] = {\n      ...currentItem,\n      [field]: processedValue,\n    } as DevisItem;\n\n    setItems(newItems);\n  };\n\n  const calculateTotal = () => {\n    return items.reduce(\n      (acc, item) => acc + Number(item.quantity) * Number(item.unitPrice),\n      0\n    );\n  };\n\n  // --- ENREGISTREMENT FINAL ---\n  const handleSubmit = async (e: React.FormEvent) => {\n    e.preventDefault();\n    setIsSubmitting(true);\n\n    try {\n      await fetchWithAuth(\"/devis\", {\n        method: \"POST\",\n        body: JSON.stringify({\n          clientName,\n          items,\n          total: calculateTotal(),\n          createdAt: new Date().toISOString(),\n        }),\n      });\n\n      toast.success(\"Devis enregistré !\");\n    } catch (e) {\n      const err = e as ApiRequestError;\n\n      if (err.code === \"quota_exceeded\") {\n        toast.error(\"Quota atteint. Passez en PRO pour continuer.\");\n      } else {\n        toast.error(err.message || \"Impossible d'enregistrer le devis\");\n      }\n    } finally {\n      setIsSubmitting(false);\n    }\n  };\n\n  return (\n    <div className=\"max-w-4xl mx-auto p-4 md:p-8\">\n      <div className=\"bg-[var(--theme-card)] rounded-3xl shadow-xl border border-slate-100 overflow-hidden\">\n        {/* HEADER AVEC ACTIONS IA */}\n        <div className=\"p-6 border-b border-slate-50 bg-[var(--theme-bg)]/50 flex flex-col md:flex-row justify-between items-center gap-4\">\n          <div>\n            <h1 className=\"text-2xl font-black text-[var(--theme-text)] uppercase tracking-tight\">\n              Nouveau Devis\n            </h1>\n            <p className=\"text-slate-500 text-sm\">\n              Remplissez les champs ou dictez votre devis\n            </p>\n          </div>\n          <DevisAiActions onAnalysisComplete={handleAiAnalysis} />\n        </div>\n\n        <form onSubmit={handleSubmit} className=\"p-6 md:p-8 space-y-8\">\n          {/* SECTION CLIENT */}\n          <div className=\"space-y-4\">\n            <label className=\"text-sm font-bold text-slate-700 uppercase tracking-widest\">\n              Client\n            </label>\n            <input\n              type=\"text\"\n              value={clientName}\n              onChange={(e) => setClientName(e.target.value)}\n              className=\"w-full p-4 rounded-2xl bg-[var(--theme-bg)] border border-[var(--theme-border)] focus:bg-[var(--theme-card)] focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all font-medium\"\n              placeholder=\"Nom du client...\"\n              required\n            />\n          </div>\n\n          {/* SECTION LIGNES DE DEVIS */}\n          <div className=\"space-y-4\">\n            <div className=\"flex justify-between items-center\">\n              <label className=\"text-sm font-bold text-slate-700 uppercase tracking-widest\">\n                Détails de la prestation\n              </label>\n              <button\n                type=\"button\"\n                onClick={addItem}\n                className=\"text-sm font-bold text-blue-600 hover:text-blue-700 flex items-center gap-1 bg-blue-50 px-3 py-1 rounded-full transition-colors\"\n              >\n                <Plus className=\"w-4 h-4\" /> Ligne\n              </button>\n            </div>\n\n            <div className=\"space-y-3\">\n              {items.map((item, index) => (\n                <div\n                  key={index}\n                  className=\"group flex flex-col md:flex-row gap-3 p-4 rounded-2xl border border-slate-100 bg-[var(--theme-card)] hover:border-blue-200 transition-all shadow-sm\"\n                >\n                  <div className=\"flex-[4]\">\n                    <input\n                      type=\"text\"\n                      placeholder=\"Ex: Pose de carrelage salle de bain\"\n                      value={item.description}\n                      onChange={(e) =>\n                        updateItem(index, \"description\", e.target.value)\n                      }\n                      className=\"w-full bg-transparent font-medium outline-none text-slate-800\"\n                    />\n                  </div>\n\n                  <div className=\"flex-[1] flex items-center gap-2 border-l md:pl-4 border-slate-100\">\n                    <span className=\"text-[10px] text-slate-400 font-bold md:hidden\">\n                      Qté:\n                    </span>\n                    <input\n                      type=\"number\"\n                      step=\"any\"\n                      value={item.quantity}\n                      onChange={(e) =>\n                        updateItem(index, \"quantity\", e.target.value)\n                      }\n                      className=\"w-full bg-transparent outline-none text-center font-bold\"\n                    />\n                  </div>\n\n                  <div className=\"flex-[2] flex items-center gap-2 border-l md:pl-4 border-slate-100\">\n                    <span className=\"text-[10px] text-slate-400 font-bold md:hidden\">\n                      Prix:\n                    </span>\n                    <input\n                      type=\"number\"\n                      step=\"any\"\n                      value={item.unitPrice}\n                      onChange={(e) =>\n                        updateItem(index, \"unitPrice\", e.target.value)\n                      }\n                      className=\"w-full bg-transparent outline-none text-right font-black text-blue-600\"\n                    />\n                    <span className=\"text-slate-400 font-bold\">€</span>\n                  </div>\n\n                  <button\n                    type=\"button\"\n                    onClick={() => removeItem(index)}\n                    className=\"p-2 text-slate-300 hover:text-red-500 transition-colors\"\n                    title=\"Supprimer la ligne\"\n                  >\n                    <Trash2 className=\"w-5 h-5\" />\n                  </button>\n                </div>\n              ))}\n            </div>\n          </div>\n\n          {/* TOTAL & SUBMIT */}\n          <div className=\"pt-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6\">\n            <div className=\"bg-slate-900 rounded-2xl p-4 px-8 text-white flex items-center gap-4 shadow-xl\">\n              <Calculator className=\"w-6 h-6 text-blue-400\" />\n              <div>\n                <p className=\"text-[10px] uppercase font-bold text-slate-400 leading-none mb-1\">\n                  Total TTC\n                </p>\n                <p className=\"text-3xl font-black tracking-tighter\">\n                  {calculateTotal().toLocaleString(\"fr-FR\", {\n                    minimumFractionDigits: 2,\n                  })}{\" \"}\n                  €\n                </p>\n              </div>\n            </div>\n\n            <button\n              type=\"submit\"\n              disabled={isSubmitting}\n              className=\"w-full md:w-auto bg-blue-600 hover:bg-blue-700 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-3 disabled:opacity-50 active:scale-95\"\n            >\n              {isSubmitting ? (\n                <Loader2 className=\"animate-spin w-6 h-6\" />\n              ) : (\n                <Save className=\"w-6 h-6\" />\n              )}\n              Enregistrer\n            </button>\n          </div>\n        </form>\n      </div>\n    </div>\n  );\n};\n",
  "apps/frontend/src/features/ai/AiModePanel.tsx": "// apps/frontend/src/features/ai/AiModePanel.tsx\nimport { Sparkles } from \"lucide-react\";\n\nexport default function AiModePanel() {\n  return (\n    <div className=\"p-4 space-y-4\">\n      <div className=\"bg-[var(--theme-card)] rounded-3xl border border-slate-100 shadow-sm p-4\">\n        <div className=\"flex items-center gap-2\">\n          <Sparkles size={16} className=\"text-purple-600\" />\n          <h3 className=\"text-xs font-black uppercase tracking-widest text-[var(--theme-text)]\">\n            Stratégie IA\n          </h3>\n        </div>\n\n        <p className=\"mt-3 text-sm text-slate-600 font-semibold\">\n          Fonctionnalité en préparation.\n        </p>\n\n        <div className=\"mt-3 text-xs text-slate-500\">\n          Cette section proposera bientôt :\n          <ul className=\"list-disc ml-5 mt-2 space-y-1\">\n            <li>Recommandations automatiques après analyse Compta</li>\n            <li>Alertes (TVA, marge, trésorerie, anomalies)</li>\n            <li>Plan d’actions priorisé</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "apps/frontend/src/features/ai/ExpertChatPanel.tsx": "// apps/frontend/src/features/ai/ExpertChatPanel.tsx\nimport React, { useCallback, useEffect, useMemo, useRef, useState } from \"react\";\nimport { Send, Bot, User, Loader2, Trash2 } from \"lucide-react\";\nimport { useAuth } from \"../../store/auth.store\";\nimport { ApiRequestError, toApiRequestError } from \"../../utils/apiRequestError\";\nimport type { AiRunResponse } from \"../../api/types\";\n\nfunction normalizeBaseUrl(input: string): string {\n  const trimmed = String(input || \"\").trim().replace(/\\/$/, \"\");\n  if (trimmed.endsWith(\"/ai\")) return trimmed.slice(0, -3);\n  return trimmed;\n}\n\nconst API_BASE = normalizeBaseUrl(\n  (import.meta as any).env?.VITE_API_URL || \"http://localhost:8080\"\n);\nconst AI_URL = `${API_BASE}/ai`;\n\nexport type ExpertMessage = {\n  id: string;\n  role: \"assistant\" | \"user\";\n  content: string;\n  timestamp: Date;\n};\n\nconst PROMPT_MAX = 2500;\n\nexport default function ExpertChatPanel({\n  analysisId,\n  setAnalysisId,\n  messages,\n  setMessages,\n}: {\n  analysisId: string | null;\n  setAnalysisId: (id: string | null) => void;\n  messages: ExpertMessage[];\n  setMessages: React.Dispatch<React.SetStateAction<ExpertMessage[]>>;\n}) {\n  const { accessToken } = useAuth();\n  const scrollRef = useRef<HTMLDivElement | null>(null);\n\n  const [input, setInput] = useState(\"\");\n  const [isLoading, setIsLoading] = useState(false);\n\n  const pollAbortRef = useRef<AbortController | null>(null);\n\n  const getWelcomeMessage = useCallback(() => {\n    if (analysisId) {\n      return \"Analyse expert activée ! Que veux-tu optimiser (TVA, charges, marge, trésorerie) ?\";\n    }\n    return \"Mode Expert IA activé. Dis-moi ce que tu veux optimiser (TVA, charges, marge, trésorerie).\";\n  }, [analysisId]);\n\n  useEffect(() => {\n    return () => {\n      try {\n        pollAbortRef.current?.abort();\n      } catch {}\n    };\n  }, []);\n\n  useEffect(() => {\n    if (!scrollRef.current) return;\n    scrollRef.current.scrollTop = scrollRef.current.scrollHeight;\n  }, [messages, isLoading]);\n\n  const clearChat = () => {\n    setMessages([\n      {\n        id: \"welcome\",\n        role: \"assistant\",\n        content: getWelcomeMessage(),\n        timestamp: new Date(),\n      },\n    ]);\n  };\n\n  const pollJobStatus = useCallback(\n    async (jobId: string) => {\n      try {\n        pollAbortRef.current?.abort();\n      } catch {}\n\n      const controller = new AbortController();\n      pollAbortRef.current = controller;\n\n      let delayMs = 1500;\n      const maxDelayMs = 12000;\n\n      const schedule = (ms: number) => new Promise((r) => setTimeout(r, ms));\n\n      while (true) {\n        if (controller.signal.aborted) {\n          setIsLoading(false);\n          return;\n        }\n\n        const res = await fetch(`${AI_URL}/status/${jobId}`, {\n          headers: accessToken\n            ? { Authorization: `Bearer ${accessToken}` }\n            : undefined,\n          signal: controller.signal,\n        });\n\n        if (controller.signal.aborted) {\n          setIsLoading(false);\n          return;\n        }\n\n        if (res.status === 304) {\n          await schedule(delayMs);\n          continue;\n        }\n\n        if (res.status === 429) {\n          delayMs = Math.min(maxDelayMs, delayMs * 2);\n          await schedule(delayMs);\n          continue;\n        }\n\n        if (!res.ok) throw await toApiRequestError(res);\n\n        const data = (await res.json()) as any;\n        const status = data?.status;\n\n        if (status === \"completed\") {\n          const raw =\n            data?.result?.text ??\n            data?.result?.response ??\n            data?.result ??\n            \"Réponse reçue.\";\n\n          const normalized =\n            typeof raw === \"string\"\n              ? raw\n              : typeof raw === \"object\" &&\n                raw !== null &&\n                \"response\" in raw\n              ? String((raw as any).response ?? \"\")\n              : String(raw);\n\n          setMessages((prev) => [\n            ...prev,\n            {\n              id: `a-${Date.now()}`,\n              role: \"assistant\",\n              content: normalized,\n              timestamp: new Date(),\n            },\n          ]);\n\n          setIsLoading(false);\n          return;\n        }\n\n        if (status === \"failed\") {\n          const msg =\n            data?.error?.message ||\n            data?.error ||\n            \"Une erreur est survenue côté IA.\";\n\n          setMessages((prev) => [\n            ...prev,\n            {\n              id: `a-${Date.now()}`,\n              role: \"assistant\",\n              content: String(msg),\n              timestamp: new Date(),\n            },\n          ]);\n\n          setIsLoading(false);\n          return;\n        }\n\n        delayMs = Math.min(maxDelayMs, Math.round(delayMs * 1.15));\n        await schedule(delayMs);\n      }\n    },\n    [accessToken, setMessages]\n  );\n\n  const send = async () => {\n    const q = input.trim();\n    if (!q || isLoading) return;\n\n    if (!accessToken) {\n      setMessages((prev) => [\n        ...prev,\n        {\n          id: `auth-${Date.now()}`,\n          role: \"assistant\",\n          content: \"Tu n’es pas authentifié. Connecte-toi puis réessaie.\",\n          timestamp: new Date(),\n        },\n      ]);\n      return;\n    }\n\n    setMessages((prev) => [\n      ...prev,\n      { id: `u-${Date.now()}`, role: \"user\", content: q, timestamp: new Date() },\n    ]);\n\n    setInput(\"\");\n    setIsLoading(true);\n\n    try {\n      const finalPrompt =\n        q.length > PROMPT_MAX\n          ? q.slice(0, PROMPT_MAX - 30) + \"\\n...[TRUNCATED]\"\n          : q;\n\n      const res = await fetch(`${AI_URL}/expert/chat`, {\n        method: \"POST\",\n        headers: {\n          Authorization: `Bearer ${accessToken}`,\n          \"Content-Type\": \"application/json\",\n        },\n        body: JSON.stringify({\n          analysisId,\n          prompt: finalPrompt,\n        }),\n      });\n\n      if (!res.ok) throw await toApiRequestError(res);\n\n      const json = (await res.json()) as AiRunResponse;\n      const jobId = (json as any)?.jobId;\n\n      if (!jobId) {\n        setIsLoading(false);\n        return;\n      }\n\n      await pollJobStatus(String(jobId));\n    } catch (e) {\n      const err = e as ApiRequestError;\n\n      setIsLoading(false);\n\n      let msg = err.message || \"Erreur lors du traitement.\";\n\n      if ((err as any).code === \"quota_exceeded\") {\n        msg = \"Quota mensuel atteint. Passe en PRO pour continuer.\";\n      } else if ((err as any).status === 429) {\n        msg = \"Trop de requêtes. Réessaie dans quelques secondes.\";\n      }\n\n      setMessages((prev) => [\n        ...prev,\n        {\n          id: `a-${Date.now()}`,\n          role: \"assistant\",\n          content: msg,\n          timestamp: new Date(),\n        },\n      ]);\n    }\n  };\n\n  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {\n    if (e.key === \"Enter\" && !e.shiftKey) {\n      e.preventDefault();\n      void send();\n    }\n  };\n\n  const headerTitle = useMemo(() => {\n    if (analysisId) return \"Expert IA (Compta)\";\n    return \"Expert IA\";\n  }, [analysisId]);\n\n  return (\n    <div className=\"h-full flex flex-col\">\n      <div className=\"flex items-center justify-between px-4 py-3 border-b bg-[var(--theme-card)]\">\n        <div className=\"font-black text-[var(--theme-text)]\">{headerTitle}</div>\n        <button\n          onClick={clearChat}\n          className=\"p-2 rounded-xl hover:bg-slate-100\"\n        >\n          <Trash2 className=\"w-5 h-5 text-slate-700\" />\n        </button>\n      </div>\n\n      <div ref={scrollRef} className=\"flex-1 overflow-y-auto p-4 space-y-3\">\n        {messages.map((m) => (\n          <div\n            key={m.id}\n            className={`flex items-start gap-2 ${\n              m.role === \"user\" ? \"justify-end\" : \"justify-start\"\n            }`}\n          >\n            {m.role !== \"user\" && (\n              <div className=\"w-8 h-8 rounded-xl bg-slate-900 text-white flex items-center justify-center\">\n                <Bot className=\"w-4 h-4\" />\n              </div>\n            )}\n\n            <div\n              className={`max-w-[82%] rounded-2xl px-4 py-3 text-sm shadow-sm ${\n                m.role === \"user\"\n                  ? \"bg-slate-900 text-white\"\n                  : \"bg-[var(--theme-card)] border text-[var(--theme-text)]\"\n              }`}\n            >\n              {m.content}\n            </div>\n\n            {m.role === \"user\" && (\n              <div className=\"w-8 h-8 rounded-xl bg-slate-200 flex items-center justify-center\">\n                <User className=\"w-4 h-4\" />\n              </div>\n            )}\n          </div>\n        ))}\n\n        {isLoading && (\n          <div className=\"flex items-start gap-2\">\n            <div className=\"w-8 h-8 rounded-xl bg-slate-900 text-white flex items-center justify-center\">\n              <Bot className=\"w-4 h-4\" />\n            </div>\n\n            <div className=\"bg-[var(--theme-card)] border rounded-2xl px-4 py-3 text-sm flex items-center gap-2\">\n              <Loader2 className=\"w-4 h-4 animate-spin\" />\n              Analyse en cours...\n            </div>\n          </div>\n        )}\n      </div>\n\n      <div className=\"p-4 border-t bg-[var(--theme-card)]\">\n        <div className=\"flex items-center gap-2\">\n          <input\n            value={input}\n            onChange={(e) => setInput(e.target.value)}\n            onKeyDown={onKeyDown}\n            placeholder=\"Ex: TVA\"\n            className=\"flex-1 px-4 py-3 rounded-2xl border bg-[var(--theme-bg)] focus:outline-none\"\n            disabled={isLoading}\n          />\n\n          <button\n            onClick={() => void send()}\n            disabled={isLoading || !input.trim()}\n            className=\"px-4 py-3 rounded-2xl bg-slate-900 text-white font-black disabled:opacity-50 flex items-center gap-2\"\n          >\n            <Send className=\"w-4 h-4\" />\n            Envoyer\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "apps/frontend/src/features/ai/ExpertHubPanel.tsx": "// apps/frontend/src/features/ai/ExpertHubPanel.tsx\nimport React, { useEffect, useRef, useState } from \"react\";\nimport { MessageSquare, TrendingUp } from \"lucide-react\";\nimport ExpertChatPanel from \"./ExpertChatPanel\";\nimport AiModePanel from \"./AiModePanel\";\nimport { fetchWithAuth } from \"../../auth/fetchWithAuth\";\n\nexport type ExpertTab = \"chat\" | \"strategy\";\n\nexport type ExpertMessage = {\n  id: string;\n  role: \"user\" | \"assistant\";\n  content: string;\n  timestamp: Date;\n};\n\ntype ExpertHistoryItem = {\n  id?: string;\n  role: string;\n  content: string;\n  createdAt?: string;\n};\n\ntype ExpertConversationResponse = {\n  success: boolean;\n  messages?: ExpertHistoryItem[];\n};\n\nexport default function ExpertHubPanel({\n  activeTab,\n  onChangeTab,\n  analysisId,\n  setAnalysisId,\n  messages,\n  setMessages,\n}: {\n  activeTab: ExpertTab;\n  onChangeTab: (tab: ExpertTab) => void;\n\n  analysisId: string | null;\n  setAnalysisId: (id: string | null) => void;\n\n  messages: ExpertMessage[];\n  setMessages: React.Dispatch<React.SetStateAction<ExpertMessage[]>>;\n}) {\n  const hydratedKeyRef = useRef<string | null>(null);\n  const [hydrationDone, setHydrationDone] = useState(false);\n\n  useEffect(() => {\n    let cancelled = false;\n\n    const key =\n      analysisId && analysisId.trim().length > 0 ? analysisId.trim() : \"last\";\n\n    // ✅ FIX MINIMAL : ne pas \"skip\" si on n'a pas de vrais messages\n    // (après clearChat() on retombe à [welcome] et on doit pouvoir re-hydrater)\n    const hasRealMessages =\n      Array.isArray(messages) && messages.some((m) => m.id !== \"welcome\");\n\n    if (hydratedKeyRef.current === key && hasRealMessages) {\n      setHydrationDone(true);\n      return;\n    }\n    hydratedKeyRef.current = key;\n\n    (async () => {\n      try {\n        // ✅ MODIF UNIQUE : on hydrate même si seul le message \"welcome\" est présent\n        if (hasRealMessages) {\n          return;\n        }\n\n        const url =\n          key !== \"last\"\n            ? `/ai/expert/history?analysisId=${encodeURIComponent(key)}`\n            : `/ai/expert/history`;\n\n        const data = await fetchWithAuth<ExpertConversationResponse>(url, {\n          method: \"GET\",\n        });\n\n        if (cancelled) return;\n\n        const raw = Array.isArray(data?.messages) ? data.messages : [];\n        if (raw.length === 0) return;\n\n        const mapped: ExpertMessage[] = raw\n          .map((m) => {\n            const role: ExpertMessage[\"role\"] =\n              m.role === \"user\" ? \"user\" : \"assistant\";\n\n            return {\n              id: String(m.id ?? `h-${Math.random().toString(16).slice(2)}`),\n              role,\n              content: String(m.content ?? \"\"),\n              timestamp: m.createdAt ? new Date(m.createdAt) : new Date(),\n            };\n          })\n          .filter((m) => m.content.trim().length > 0);\n\n        if (mapped.length > 0) {\n          setMessages(mapped);\n        }\n      } catch {\n        // best effort\n      } finally {\n        if (!cancelled) setHydrationDone(true);\n      }\n    })();\n\n    return () => {\n      cancelled = true;\n    };\n  }, [analysisId, messages, setMessages]);\n\n  return (\n    <div className=\"flex flex-col h-full\">\n      <div className=\"flex gap-2 p-3 bg-[var(--theme-card)] border-b border-slate-100\">\n        <button\n          onClick={() => onChangeTab(\"chat\")}\n          className={`flex-1 px-3 py-2 rounded-2xl text-xs font-black uppercase tracking-wider flex items-center justify-center gap-2 transition ${\n            activeTab === \"chat\"\n              ? \"bg-slate-900 text-white\"\n              : \"bg-[var(--theme-bg)] text-slate-700 hover:bg-slate-100\"\n          }`}\n        >\n          <MessageSquare size={14} />\n          Chat Expert\n        </button>\n\n        <button\n          onClick={() => onChangeTab(\"strategy\")}\n          className={`flex-1 px-3 py-2 rounded-2xl text-xs font-black uppercase tracking-wider flex items-center justify-center gap-2 transition ${\n            activeTab === \"strategy\"\n              ? \"bg-slate-900 text-white\"\n              : \"bg-[var(--theme-bg)] text-slate-700 hover:bg-slate-100\"\n          }`}\n        >\n          <TrendingUp size={14} />\n          Stratégie\n        </button>\n      </div>\n\n      <div className=\"flex-1 overflow-y-auto bg-[var(--theme-bg)]\">\n        {activeTab === \"chat\" ? (\n          hydrationDone ? (\n            <ExpertChatPanel\n              analysisId={analysisId}\n              setAnalysisId={setAnalysisId}\n              messages={messages}\n              setMessages={setMessages}\n            />\n          ) : (\n            <div className=\"p-4 text-sm text-slate-600\">Chargement…</div>\n          )\n        ) : (\n          <AiModePanel />\n        )}\n      </div>\n    </div>\n  );\n}\n",
  "apps/frontend/src/features/ai/assistant/AssistantPanel.tsx": "// apps/frontend/src/features/ai/assistant/AssistantPanel.tsx\nimport { useState, useRef, useEffect } from \"react\";\nimport { Send, Bot, User, Loader2 } from \"lucide-react\";\nimport { fetchWithAuth } from \"../../../auth/fetchWithAuth\";\nimport { useExpertAssistantStore } from \"../expertAssistant.store\";\n\ninterface Message {\n  id: string;\n  role: \"assistant\" | \"user\";\n  content: string;\n}\n\ninterface Props {\n  variant?: \"page\" | \"bubble\";\n}\n\nexport default function AssistantPanel({ variant = \"page\" }: Props) {\n  const [messages, setMessages] = useState<Message[]>([\n    {\n      id: \"welcome\",\n      role: \"assistant\",\n      content: \"Bonjour 👋 Je suis votre assistant expert.\",\n    },\n  ]);\n\n  const [analysisContext, setAnalysisContext] = useState<any>(null);\n\n  const payload = useExpertAssistantStore((s) => s.payload);\n  const clear = useExpertAssistantStore((s) => s.clear);\n\n  const [input, setInput] = useState(\"\");\n  const [loading, setLoading] = useState(false);\n  const scrollRef = useRef<HTMLDivElement>(null);\n\n  useEffect(() => {\n    if (!payload) return;\n\n    if (payload.analysisData) {\n      setAnalysisContext(payload.analysisData);\n    }\n\n    if (payload.message != null) {\n      setMessages((prev) => [\n        ...prev,\n        {\n          id: `payload-${Date.now()}`,\n          role: \"assistant\",\n          content: payload.message ?? \"\",\n        },\n      ]);\n    }\n\n    clear();\n  }, [payload, clear]);\n\n  useEffect(() => {\n    if (scrollRef.current) {\n      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;\n    }\n  }, [messages, loading]);\n\n  const handleSend = async () => {\n    if (!input.trim() || loading) return;\n\n    const userMsg: Message = {\n      id: Date.now().toString(),\n      role: \"user\",\n      content: input,\n    };\n\n    setMessages((prev) => [...prev, userMsg]);\n    setInput(\"\");\n    setLoading(true);\n\n    try {\n      let finalPrompt = input;\n      if (analysisContext) {\n        finalPrompt = `CONTEXTE COMPTA: ${JSON.stringify(\n          analysisContext\n        )}\\n\\nQUESTION: ${input}`;\n      }\n\n      const data = await fetchWithAuth<{ result?: string; jobId?: string }>(\n        \"/ai/chat\",\n        {\n          method: \"POST\",\n          body: JSON.stringify({\n            type: \"expert\",\n            prompt: finalPrompt,\n            context: analysisContext ?? undefined,\n          }),\n        }\n      );\n\n      const botMsg: Message = {\n        id: Date.now().toString(),\n        role: \"assistant\",\n        content: data?.result || \"Réponse IA indisponible.\",\n      };\n\n      setMessages((prev) => [...prev, botMsg]);\n    } catch {\n      setMessages((prev) => [\n        ...prev,\n        {\n          id: \"error\",\n          role: \"assistant\",\n          content: \"Erreur lors de la réponse IA.\",\n        },\n      ]);\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  return (\n    <div\n      className={`flex flex-col ${\n        variant === \"bubble\"\n          ? \"h-[500px]\"\n          : \"h-[calc(100vh-140px)] max-w-4xl mx-auto\"\n      }`}\n    >\n      <div\n        ref={scrollRef}\n        className=\"flex-1 overflow-y-auto p-4 space-y-4 bg-[var(--theme-bg)]\"\n      >\n        {messages.map((msg) => (\n          <div\n            key={msg.id}\n            className={`flex ${\n              msg.role === \"user\" ? \"justify-end\" : \"justify-start\"\n            }`}\n          >\n            <div\n              className={`px-4 py-2 rounded-2xl text-sm ${\n                msg.role === \"user\"\n                  ? \"bg-blue-600 text-white\"\n                  : \"bg-[var(--theme-card)] border border-slate-100\"\n              }`}\n            >\n              {msg.content}\n            </div>\n          </div>\n        ))}\n\n        {loading && (\n          <div className=\"flex items-center gap-2 text-slate-400 text-sm\">\n            <Loader2 size={16} className=\"animate-spin\" />\n            Réflexion en cours...\n          </div>\n        )}\n      </div>\n\n      <div className=\"p-3 border-t bg-[var(--theme-card)] flex gap-2\">\n        <input\n          value={input}\n          onChange={(e) => setInput(e.target.value)}\n          onKeyDown={(e) => e.key === \"Enter\" && handleSend()}\n          placeholder=\"Posez votre question...\"\n          className=\"flex-1 px-4 py-2 rounded-xl bg-slate-100 outline-none\"\n        />\n        <button\n          onClick={handleSend}\n          className=\"bg-slate-900 text-white px-4 rounded-xl\"\n        >\n          <Send size={16} />\n        </button>\n      </div>\n    </div>\n  );\n}\n",
  "apps/frontend/src/pages/Help.tsx": "// apps/frontend/src/pages/Help.tsx\nimport React from \"react\";\n\nexport default function Help() {\n  const openExpertChat = () => {\n    window.dispatchEvent(new Event(\"openExpertChat\"));\n  };\n\n  return (\n    <div className=\"p-6 max-w-3xl mx-auto\">\n      <h2 className=\"text-2xl font-black text-[var(--theme-text)]\">Aide</h2>\n      <p className=\"text-slate-600 mt-2\">\n        Retrouvez ici l’aide rapide et l’accès au Mode Expert IA.\n      </p>\n\n      <div className=\"mt-6 bg-[var(--theme-card)] border border-slate-100 rounded-2xl p-5 shadow-sm\">\n        <h3 className=\"font-bold text-[var(--theme-text)]\">Besoin d’un expert ?</h3>\n        <p className=\"text-slate-600 text-sm mt-1\">\n          Ouvre la bulle “Mode Expert IA” directement.\n        </p>\n\n        <button\n          onClick={openExpertChat}\n          className=\"mt-4 px-4 py-2 rounded-xl bg-slate-900 text-white font-bold hover:opacity-90\"\n        >\n          Ouvrir le Mode Expert IA\n        </button>\n      </div>\n\n      <div className=\"mt-6 bg-[var(--theme-card)] border border-slate-100 rounded-2xl p-5 shadow-sm\">\n        <h3 className=\"font-bold text-[var(--theme-text)]\">Raccourcis</h3>\n        <ul className=\"mt-3 text-sm text-slate-700 space-y-2 list-disc pl-5\">\n          <li><b>VISION</b> : suivi photo / analyse</li>\n          <li><b>DEVIS</b> : gestion devis</li>\n          <li><b>COMPTA</b> : suivi compta</li>\n        </ul>\n      </div>\n    </div>\n  );\n}\n"
};

const repoRoot = process.cwd();
const written = [];
const missingDirs = new Set();

for (const [relativePath, content] of Object.entries(FILES)) {
  const absolutePath = path.join(repoRoot, relativePath);
  const dir = path.dirname(absolutePath);

  if (!fs.existsSync(dir)) {
    missingDirs.add(dir);
    fs.mkdirSync(dir, { recursive: true });
  }

  fs.writeFileSync(absolutePath, content, "utf8");
  written.push(relativePath);
}

console.log(`✅ Theme patches applied to ${written.length} files.`);
for (const file of written) {
  console.log(` - ${file}`);
}
